INSERT INTO `db_lugat` (`id`, `indeks`, `kelime`, `kirpilmis`, `anlam`) VALUES
(1, 'A0', 'A', 'a', ' 1928 senesinde alınan Türk alfabesinin "a" harfi, Osmanlıcadaki elif ve ayın harflerine yakın bir ses verir.'),
(2, 'A0', 'A', 'a', ' Nida edatı olup, kelimenin sonuna gelir "ey" mânası verir. Aynı veya farklı iki kelime arasına gelirse, sözün mânasını kuvvetlendirir. "rengârenk, lebaleb" gibi.'),
(3, 'A0', 'AB', 'ab', ' f. Su. * Mc : Yağmur. * Letâfet, güzellik. * İtibar. * Irz, nâmus. * Vakar. * Cilâ. *Keskinlik.'),
(4, 'A0', 'AB-I ÂBİSTENÎ', 'ab-ı abisteni', ' Nebatların beslenip büyümesi için zaruri olan su ve yağmur. * Gebeliğe sebep olan su, meni.'),
(5, 'A0', 'AB-I ADÂLET', 'ab-ı adalet', ' Doğruluğun ve adaletin feyz ve bereketi.'),
(6, 'A0', 'AB-I BÂDE-RENG', 'ab-ı bade-reng', ' Kanlı göz yaşı.'),
(7, 'A0', 'AB-I BESTE', 'ab-ı beste', ' Buz. * Mc : Billur, sırça.'),
(8, 'A0', 'AB-I CİĞER', 'ab-ı ciğer', ' Ciğer suyu. * Göz yaşı. '),
(9, 'A0', 'AB-I ÇEŞM', 'ab-ı çeşm', ' Göz yaşı.'),
(10, 'A0', 'AB-I DEHÂN', 'ab-ı dehan', ' Ağız suyu, salya.'),
(11, 'A0', 'AB-I HAYAT', 'ab-ı hayat', ' Kan. Ebedî hayata sebep olan hayat suyu (diye tâbir edilen) bu kelime, edebiyatta : "çok güzel ifâde, lâtif söz, parlaklık, letâfet" mânalarında geçer. * Tas : Aşk-ı hakiki, aşk-ı ilâhi, ilm-i ledün, mârifetullah''tan kinayedir. Âb-ı Hızır, âb-ı hayvan, âb-ı beka gibi isimlerle de söylenir.'),
(12, 'A0', 'AB-I HUFTE', 'ab-ı hufte', ' Durgun su. * Buz. * Billur. * Kınında bulunan kılınç.'),
(13, 'A0', 'AB-I HURDENÎ', 'ab-ı hurdeni', ' İçme suyu. İçilir su.'),
(14, 'A0', 'AB-I KEVSER', 'ab-ı kevser', ' Kevser âb-ı hayatı. Kevser letâfeti.'),
(15, 'A0', 'AB-I LEZİZ', 'ab-ı leziz', ' Leziz, tatlı su.'),
(16, 'A0', 'AB-I MUSAFFÂ', 'ab-ı musaffa', ' Temizlenmiş, tasfiye edilmiş su. Saf su.'),
(17, 'A0', 'AB-I REVAN', 'ab-ı revan', ' Akar su. * Kalpteki ferahlık.'),
(18, 'A0', 'AB-I RÛY', 'ab-ı ruy', ' Yüz suyu, şeref, haysiyet, nâmus.'),
(19, 'A0', 'AB-I ŞOR', 'ab-ı şor', ' Acı su. * Göz yaşı.'),
(20, 'A0', 'AB-I YAH', 'ab-ı yah', ' Buzlu, soğuk su.'),
(21, 'A0', 'AB-I ZEN', 'ab-ı zen', ' f. Küçük havuz. * Su birikintisi. * Yumuşak, lâtif sözlerle hatır alan ve bu manâda emir. (Bak : Avzen)'),
(22, 'A0', 'AB', 'ab', ' Kusur, ayıp, noksanlık.'),
(23, 'A0', 'ABA''', 'aba''', ' Kaba, ahmak kişi.'),
(24, 'A0', 'A''BA', 'a''ba', ' Ağırlıklar, yükler, mes''uliyetler. * Sandık.'),
(25, 'A0', 'ABA', 'aba', ' Ekseriyetle yünden yapılmış, bol giyimli bir libas, elbise. (Peygamber Efendimiz de (A.S.M.) bu libası giyerlerdi.)'),
(26, 'A0', 'ÂBÂ', 'aba', ' (Eb. C.) Babalar, pederler. * Mc : Mürşidler, ileri gelenler.'),
(27, 'A0', 'ÂBÂ VE ECDÂD', 'aba ve ecdad', ' Analar, babalar, dedeler.'),
(28, 'A0', 'AB''AB', 'ab''ab', ' Taze civanlık. * İbrişim halı. * Dağ tekesi. * Yumuşak yünden yapılan kisve.'),
(29, 'A0', 'ÂBAB', 'abab', ' Otu bol olan yerler, çayırlar, otlaklar, mer''alar.'),
(30, 'A0', 'ABAB', 'abab', ' (Abb) Suyu nefes almadan içmek. * Işık, nur, ziyâ.'),
(31, 'A0', 'AB''ÂB', 'ab''ab', ' Uzun boylu kimse. * Güzel huylu ve sabırlı adam.'),
(32, 'A0', 'ABAD', 'abad', ' Ebedler. Sonsuz gelecek zamanlar.'),
(33, 'A0', 'ABAD', 'abad', ' f. Mâmur, şen. * Çok dolu.'),
(34, 'A0', 'A''BAD', 'a''bad', ' Köleler.'),
(35, 'A0', 'ABADAN', 'abadan', ' f. Mâmur, şen. İmâr edilmiş.'),
(36, 'A0', 'ABADÎ', 'abadi', ' Bayındırlık, mâmurluk, şenlik. * İmar edilmiş olan. * Hindistan''ın Devlet-âbad şehrinde ipekden yapılmış bir yazı kağıdı. '),
(37, 'A0', 'ABÂDİLE', 'abadile', ' Abdullah isimliler.'),
(38, 'A0', 'ABÂDİLE-İ SEB''A', 'abadile-i seb''a', ' Meşhur olan yedi Abdullah isimli sahabe-i kiram (R.A.) (Abdullah İbn-i Abbas, Abdullah İbn-i Ömer, Abdullah İbn-i Mes''ud, Abdullah İbn-i Ravâha, Abdullah İbn-i Selam, Abdullah bin Amr bin As, Abdullah bin ebi Evfâ (R.A.) (Asr-ı saadette Abdullah ismiyle anılan ikiyüz yirmi sahabe-i kiram hazerâtı vardı.)'),
(39, 'A0', 'ABAJUR', 'abajur', ' Fr. Lamba siperi.'),
(40, 'A0', 'ABAK', 'abak', ' İcab etmek. Lâzım olmak. * Yapışmak.'),
(41, 'A0', 'ABAKİYE', 'abakiye', ' Lâzım olmak. * Yapışmak. * Zahmet.'),
(42, 'A0', 'ÂBAL', 'abal', ' Develer.'),
(43, 'A0', 'ABAL', 'abal', ' Dağ kili.'),
(44, 'A0', 'ABALET', 'abalet', ' Ağırlık.'),
(45, 'A0', 'ABA', 'aba', ' Kule.'),
(46, 'A0', 'ABAM', 'abam', ' şişman kimse.'),
(47, 'A0', 'ABA-PUŞ', 'aba-puş', ' f. Aba giyen, derviş. * Fakir.'),
(48, 'A0', 'ÂBAR', 'abar', ' (Bi''r. C.) Kuyular. Su kuyuları. * f. Hesap defteri.'),
(49, 'A0', 'ABAT', 'abat', ' Koltuk altları. '),
(50, 'A0', 'ABB', 'abb', ' Işık, nur, ziya. * Güzelleşme. '),
(51, 'A0', 'ABBAS', 'abbas', ' Resul-i Ekrem Aleyhissalâtu Vesselâmın amcalarındandır ve Mekke''nin fethinde Müslüman olmuştur. * Arslan, gazanfer.'),
(52, 'A0', 'ABBASÎ', 'abbasi', ' Resul-i Ekrem''in (A. S.M.) amcası Hz. Abbas''ın neslinden gelen veya aynı sülâleden gelenlerin kurdukları devlete mensup olan.'),
(53, 'A0', 'AB-BERİN', 'ab-berin', ' f. Akarsu ve şelâle kenarlarında suyun tazyikle akmasından meydana gelen içi oyuk kovuk.'),
(54, 'A0', 'AB-CAME', 'ab-came', ' f. Su kabı.'),
(55, 'A0', 'AB-ÇERA', 'ab-çera', ' f. Kahvaltı.'),
(56, 'A0', 'ABD', 'abd', ' Kul, köle, Allah''ın kulu. Mahluk, insan. Hizmetçi. (Hür''ün zıddı). "Abd kelimesi Allah''ın bazı isimleriyle birleştirilerek erkek isimleri meydana getirilir. Abdullah (Allah''ın kulu). Abdulbâki (Ebedi olan Allah''ın kulu) gibi. Bu isimleri taşıyan insanlar buna lâyık olmaya çalışmalıdırlar."'),
(57, 'A0', 'ABDAL', 'abdal', ' t. Safdil, ahmak, bön. * Afganistan''da yaşıyan bir Türk kavminin adı, bu kavimden olan kimse. * Anadoludaki bazı göçebelerin adı ve bunlardan olan kimse. * Derviş, ermiş, kalender. Kendini Allah''a adamış. Ona teslim olmuş, bu yolda çile çekmiş kimse. (Bak : Ebdal)'),
(58, 'A0', 'ABDAN', 'abdan', ' (Ab. dan) Bahçe kovası, bahçe sulamaya mahsus süzgeçli kova. * Sidik kesesi, mesane.'),
(59, 'A0', 'ABDAR', 'abdar', ' f. Parlak. * Sağlam vücudlu. * Su veren hizmetçi. * Mc : Ter u tâze, tap taze. '),
(60, 'A0', 'AB-DEST', 'ab-dest', ' f. Namaz ve sair dini ibadetler için usulüne uygun olarak, el, ağız, burun, yüz, dirseklere kadar kolları ve topuk kemiği üzerine kadar ayakları üçer defa yıkamak ve kulaklara, başa ve enseye meshetmektir. * Azarlama, paylama.'),
(61, 'A0', 'ABDESTAN', 'abdestan', ' f. Su ibriği, abdest ibriği.'),
(62, 'A0', 'ABDEST-HANE', 'abdest-hane', ' f. Ayak yolu, helâ. * Abdest alacak yer.'),
(63, 'A0', 'ABDİYET', 'abdiyet', ' Kulluk. * Kul olduğunu bilerek dininde, emredildiği üzere ibâdet ve itaatte bulunmak.'),
(64, 'A0', 'ABDULAZİZ', 'abdulaziz', ' 32. Osmanlı Padişahıdır. Hilâfeti (Hi: 1277-1293) seneleri arasındadır. Mithat Paşa ve arkadaşları tarafından bilek damarları kesilerek şehid edilmiştir.'),
(65, 'A0', 'ABDULHAMİD LL', 'abdulhamid ll', ' (mi: 1842-1918) 34'' üncü Osmanlı Padişâhıdır. 33 yıl saltanatta kalmış olan bu şefkatli Sultan,İslâmiyete son derece bağlı idi. Yüksek bir siyaset adamı ve devlet işlerini bizzat takibeden bir zattı. Memlekette bolluk ve refahı te''min için çalıştı. (R.Aleyh)'),
(66, 'A0', 'ABDULKADİR', 'abdulkadir', ' Allah''ın kulu.'),
(67, 'A0', 'ABDULKADİR-İ GEYLANÎ', 'abdulkadir-i geylani', ' (Bak: Geylânî)'),
(68, 'A0', 'ABDULKAHİR-İ CÜRCANÎ', 'abdulkahir-i cürcani', ' (Bak: Cürcanî)'),
(69, 'A0', 'ABDULLAH', 'abdullah', ' Allah''ın kulu. * Bu isim Resul-i Ekrem Aleyhissalâtü Vesselâmın mübarek ve şerefli isimlerindendir. Çünkü, Allah''a itaat ve ibadette, kulluk yapmada devamlı ve en ileride olup bütün ömürlerinde Cenab-ı Hakka maddi manevi bütün hâlâtında itaatttan ayrılmamıştır (A.S.M.). Hem muhterem babasının adı da Abdullah''tır.'),
(70, 'A0', 'ABDULLAH İBN-İ ABBAS (R.A)', 'abdullah ibn-i abbas (r.a)', ' Ashab-ı Kiram''ın fakih ve müctehidlerindendir. Resul-i Ekrem''in (A.S.M.) amcasının oğludur. Ashâb-ı Kirâm arasında mümtaz bir mevki''e hâizdir. Sahih-i Buhari''de mezkûr olduğu üzere Resul-i Ekrem (A.S.M.), Abdullah hakkında : "İlâhi onu dinde fakih kıl ve kitabını ona öğret!" diye dua buyurmuştu. Bu âli duaya mazhariyetinden dolayı zamanın en bilgin şahsiyeti olmuştu. Resul-i Ekrem''in (A.S.M.) hadislerini ezberlemekte, tefsir, hadis, fıkıh ve ferâiz gibi yüksek ilimlerde eşsizdir. Hz. Ömer ve Osman''ın (Radiyallahü anhüma) hilâfetleri zamanında müftülük vazifesini ifâ ediyordu. Kur''anın tefsirindeki müstesna kudretinden dolayı Habr-ül-ümme, Tercemân-ül-Kur''an, Sultan-ül-Müfessirin gibi yüksek lâkablarla Ashab ve Tabiin arasında şöhret buldu. 1640 hadis rivâyet etmiştir. Hicretin 68. yılında 70 yaşında olduğu hâlde Tâif''de ebedî hayata kavuşmuştur. (R.A.)'),
(71, 'A0', 'ABDULLAH İBN-İ ÖMER', 'abdullah ibn-i ömer', ' Bi''setten bir yıl önce doğdu. Hicri yetmişüç tarihinde Haccâc-ı Zalim''in emri ile şehid edildi (R.A.) Sahabe-i Kirâmın ileri gelenlerinden ve Resul-i Ekrem Aleyhissalatü Vesselâmın çok bağlılarından ve dâima onun ahlâkını yaşamağa çalışanlardandı. Hz. Ömer Radıyallahü Anh''ın oğlu idi. Hilâfet ve Valilik işlerine hiç karışmadı. Müttaki, cömert, kanaat sahibi, halim bir zat olup kendini dünyaya bağlaması ihtimali olan bir malı olsa derhal onu sadaka verir veya hediye ederdi. (R.A.)'),
(72, 'A0', 'ABDULLAH İBN-İ ZÜBEYR', 'abdullah ibn-i zübeyr', ' Ebu Bekir-i Sıddık''ın kızı Esma''nın oğludur. Muhacirlerden ilk doğan çocuk olup cesaret, şecaat, ibadet ve takvası ile meşhurdur. Zübeyr ibn-i Avvam''ın oğludur. Yezid''in saltanatını kabul etmedi ve Mekke''de dokuz sene halifelik yaptı. 73 yaşında şehid edildi. (R.A.)'),
(73, 'A0', 'ABDURRAHMAN BİN AVF', 'abdurrahman bin avf', ' Aşere-i mübeşşereden ve çok fedakar olan Sahabelerdendir. İlk müslüman olan sekiz kişiden birisidir. Bütün ihya-yı din için olan muharebelerde çok fedakârlıkta bulunmuş, birisinde yirmibir yerinden yaralanmıştı. Bir gazada oniki dişini birden kaybetmişti. Medine''ye ve Habeşistan''a hicret edenlerdendi. Çok zengin idi. Bir defa otuz köleyi birden azad etmişti. Hicri 31 tarihinde 71 yaşında vefat etti.'),
(74, 'A0', 'ABE''', 'abe''', ' Kıymet. Ehemmiyet. Meta''. '),
(75, 'A0', 'ABE', 'abe', 'İşaret, alamet. * Cemaat, topluluk.'),
(76, 'A0', 'ABECE', 'abece', ' Ahmak kimse.'),
(77, 'A0', 'ABED', 'abed', ' Hayâ etmek. Arlanmak. * Hışım etmek, kızmak. * Uyuz hastalığı.'),
(78, 'A0', 'ABEDE', 'abede', ' (ÎÂbid. C.) İbadet edenler. Âbidler. Tapanlar.'),
(79, 'A0', 'ABEDE-İ ESNAM', 'abede-i esnam', ' f. Puta tapanlar. Putperestler. Heykele baş eğenler. '),
(80, 'A0', 'ÂBEK', 'abek', ' Sulu, su dolu olan şeyler. * Çıban. * Civa. (Hg).'),
(81, 'A0', 'ABEKET', 'abeket', ' (C.: Abekât) Tâne, az şey. * Tuluk içinde kalan yağ bakiyyesi. * Ekmek parçası. * Yılan başı dedikleri ufacık akça boncuk.'),
(82, 'A0', 'A''BEL', 'a''bel', ' Ak, beyaz. * Ağaç yaprağının dökülmesi.'),
(83, 'A0', 'ABEL', 'abel', ' (C.: Abâl) Yassı ve enli yaprak. '),
(84, 'A0', 'A''BEL', 'a''bel', ' (C: A''bile) Çok sert taş ki, kırmızı, beyaz veya siyah renkli olur. * Taşlık dağ.'),
(85, 'A0', 'AB-ENDAM', 'ab-endam', ' f. Güzellik. Güzel endam.'),
(86, 'A0', 'AB-ENDAZ', 'ab-endaz', ' Su mühendisi.'),
(87, 'A0', 'ABERASYON', 'aberasyon', ' Fr. Sapma.'),
(88, 'A0', 'ABERAT', 'aberat', ' (Abre. C.) Göz yaşları.'),
(89, 'A0', 'ABES', 'abes', ' Davarın kuyruğunda kuruyup kalan bevl ve ters.'),
(90, 'A0', 'ABES', 'abes', ' Oyuncak kabilinden faydasız ve boş amel. Lüzumsuz ve gayesiz iş. Tesadüfi. (Bak: Gaye)'),
(91, 'A0', 'ABESE', 'abese', ' (Abs. den) Çehresini çattı, sureti kerih oldu (meâlinde).'),
(92, 'A0', 'ABESE SURESİ', 'abese suresi', ' Kur''an-ı Kerim''de sekseninci surenin ismi olup, Mekke-i Mükerreme''de nazil olmuştur. Saliha Suresi, Sefere Suresi de denilir.'),
(93, 'A0', 'ABESE İRCA', 'abese irca', ' Mantık ve matematikte bir isbat şeklidir. Bir hükmün doğruluğunu isbat için, bu hükmü inkâr eden diğer hükmün yanlışlığı isbatlanır. Meselâ: Allah''ın varlığının inkâr edilmesinin imkânsızlığını veya abesiyetini göstermek, Allah''ın varlığını isbat yollarından biridir. Bu, "Abese irca" yolu ile isbat şeklidir.'),
(94, 'A0', 'ABESİYAT', 'abesiyat', ' (Abes. C.) Faydasız ve boş şeyler.'),
(95, 'A0', 'ABESİYYUN', 'abesiyyun', ' Kâinatın ve hâdiselerin başı boş, faydasız ve gayesiz, kendi kendine, Haliksız olduğuna inanmak isteyen bâtıl yoldaki felsefeciler. Zamanımızda Ekzistansializm "Varoluşculuk" adı altında yeniden ortaya çıkan bir varlık ve hayat felsefesidir. İki kola ayrılmıştır. Bunlardan uluhiyeti inkâr edenler, hayatın, varlığın ve insanın var oluşunu abes ve gayesiz sayan ehl-i dalâlet fırkalarından biridir. Hristiyanlık dünyasında bunlara karşı çıkan ikinci kısım ise: Allah''a inanılmazsa herşeyin abes olacağını, bu sebeple Allah''a inanmanın zaruriliğini müdafaa etmektedirler.(Kâinatı abes ve gayesiz itikat eden felâsife-i abesiyyun gibi kendilerini başıboş, hikmetsiz, gayesiz, vazifesiz, Haliksız mı zannediyorlar? Acaba gözleri kör olmuş, görmüyorlar mı ki, kâinat baştan aşağıya kadar hikmetlerle müzeyyen ve gayelerle müsmirdir. Ve mevcudat, zerrelerden güneşlere kadar vazifelerle muvazzaftır. Ve evamir-i İlahiyyeye müsahharlardır.S.)'),
(96, 'A0', 'ABEY-SERAN', 'abey-seran', ' Fesliğen. * Şiddetli emir. Şer ve mekruh nesne. * Bir dikenli ağaç.'),
(97, 'A0', 'AB-GAH', 'ab-gah', ' Fr. Havuz, küçük göl, su biriken yer. * Tıb : Karnın kaburga kemikleri kıkırdağı ve kısa kaburgalar altında olan kısmı. Böğür.'),
(98, 'A0', 'AB-GİNE', 'ab-gine', ' Fr. Billur. * Ayna. * Kılınç. * Göz yaşı. * Şişe, sürahi, kadeh.'),
(99, 'A0', 'AB-GİR', 'ab-gir', ' f. Suyun biriktiği yer, havuz. * Dokumacılıkta kullanılan fırça.'),
(100, 'A0', 'AB-HANE', 'ab-hane', ' f. Abdest bozacak yer. Helâ, tuvalet.'),
(101, 'A0', 'ABHER', 'abher', ' Nergis çiçeği, * Dolu kap. '),
(102, 'A0', 'AB-HURDE', 'ab-hurde', ' f. Su içen.'),
(103, 'A0', 'ABIK', 'abık', ' Sebebsiz olarak sahibi yanından kaçan köle.* Civa. (Hg)'),
(104, 'A0', 'ABÎ', 'abi', ' f. Ayva. * Suda yaşayan ve suda meydana gelen. * Çok mâvi.'),
(105, 'A0', 'ABÎ', 'abi', ' Kurban payı.'),
(106, 'A0', 'ABÎ', 'abi', ' Çekinen. * Tiksinen. * Sakınan. * Nazlanan.'),
(107, 'A0', 'ABİD', 'abid', ' İbadet eden. Zâhid. Çok ibadet eden. * Köle.'),
(108, 'A0', 'ABÎD', 'abid', ' Kullar. Köleler.'),
(109, 'A0', 'ABİD', 'abid', ' f. Kıvılcım.'),
(110, 'A0', 'ABİDANE', 'abidane', ' f. Kul olarak, ibâdet edene yakışır surette.'),
(111, 'A0', 'ABİDAT-I İSLÂMİYE', 'abidat-ı islamiye', ' İslâm medeniyeti anıtları.'),
(112, 'A0', 'ABİDE', 'abide', ' Uzun müddet dillerde destan olup kalan beliye ve dâhiye. * Bir milletin târihinde büyük bir değeri hâiz olan vak''a. * Fesahat ve belâgatı dolayısıyle benzeri söylenemeyen şiir. * Tarihte yüksek ve hâkim bir mevkide olan vak''aları veya büyükleri yaşatmak için yapılan bina. * Azametiyle, güzelliğiyle insanı hayrete uğratan mebani. (Süleymaniye ve Ayasofya câmileri gibi.) Uzun müddet yaşıyan edebî, ilmi, sinai eserler. * Geçmiş devirlerden kalma tarihi veya bedii kıymeti olan binalar, kaleler ve harabeleri. * Dikilmiş sütunlar ve bunların üzerindeki resimler, nakışlar, yazılar. * Abidenin arapçadaki manası bizdekinden başkadır: Kendisinden nefretle, haşyetle bahsolunan, uzun müddet dillerde destan olup kalan dâhiye ve beliyyeye denir. (Türk İslâm Ansiklopedisi)'),
(113, 'A0', 'ABİDE', 'abide', ' İbâdet eden kadın. (Abide-i zâhide gibi)'),
(114, 'A0', 'A''BİDE', 'a''bide', ' (Abd. C.) Köleler. Abid.'),
(115, 'A0', 'ABİDEVÎ', 'abidevi', ' Abide gibi. Abideyi andıran, âbideye benzeyen şekilde.'),
(116, 'A0', 'ABİL', 'abil', ' Koyun, at ve deve gibi hayvanlara iyi bakan. * Çayırda otlayarak suya muhtaç olmayan hayvan.'),
(117, 'A0', 'ABİLE', 'abile', ' f. Su üzerindeki kabarcık. * Sivilce. Çıban.'),
(118, 'A0', 'ABİR', 'abir', ' (Ubur''dan) Bir yerden geçen, giden yolcu. Geçen. * Hz. İbrâhimin (A.S.) dedelerinden birisinin adı.'),
(119, 'A0', 'ABİS', 'abis', ' Asık suratlı, ekşi yüzlü kimse. * Arslan.'),
(120, 'A0', 'ABİS', 'abis', ' Alaycı, saygısız. '),
(121, 'A0', 'ABİS', 'abis', ' Denizlerdeki dokuzbin metreyi geçen derinlikler.'),
(122, 'A0', 'ABÎSE', 'abise', ' (C: Abayis) Tarhana.'),
