(3426, 'B0', 'BA-DAD', 'ba-dad', ' f. Adaletli, âdil, sâdık, doğru.'),
(3427, 'B0', 'BADAM', 'badam', ' f. Badem.'),
(3428, 'B0', 'BADAME', 'badame', ' f. İpek kurdu. * Zincir halkası. * Et beni. * Nazarlık. * Süslü şey. * Eski hırka.'),
(3429, 'B0', 'BADAŞ', 'badaş', ' f. Mükâfat.'),
(3430, 'B0', 'BAD-BAN', 'bad-ban', ' f. Yelken. * Gemi sereni.'),
(3431, 'B0', 'BAD-BAZ', 'bad-baz', ' f. Yelpaze.'),
(3432, 'B0', 'BAD-BEDEST', 'bad-bedest', ' f. Elinde avucunda birşey bulunmayan. İflas etmiş.'),
(3433, 'B0', 'BAD-BER', 'bad-ber', ' f. Uçurtma. * Daima kendini methettiği halde elinden bir iş gelmiyen kimse.'),
