(3497, 'B0', 'BAGAR', 'bagar', ' Bir yakıcı hastalıktır ki devede vâki olur; suyu içip kanmaz ve sonunda ondan helâk olur.'),
(3498, 'B0', 'BAGARE', 'bagare', ' Şiddetle yağan yağmur.'),
(3499, 'B0', 'BAGAT', 'bagat', ' (Bağ. C.) Bağlar, üzüm bağları.'),
(3500, 'B0', 'BAGAYA', 'bagaya', ' (Bagiyy. C.) Fahişeler.'),
(3501, 'B0', 'BAGBAGA', 'bagbaga', ' Evmek, acele.'),
(3502, 'B0', 'BAG-BAN', 'bag-ban', ' f. Bahçıvan, bağcı. Bahçe bekçisi.'),
(3503, 'B0', 'BAG-BANÎ', 'bag-bani', ' f. Bahçıvanlık, bağcılık. Bağ bekçiliği.'),
