(5221, 'B0', 'BÎ-BEKA', 'bi-beka', ' Bekasız, devamsız.'),
(5222, 'B0', 'BİBERON', 'biberon', ' Fr. Emzik.'),
(5223, 'B0', 'BİBİ', 'bibi', ' Hala, babanın kızkardeşi.'),
