(6091, 'B0', 'BERŞAK', 'berşak', 'Ok atmak. '),
(6092, 'B0', 'BERŞA''', 'berşa''', 'Uzun boylu, iri gövdeli ahmak kimse. '),
(6093, 'B0', 'BERK-EFŞAN', 'berk-efşan', 'f. Şimşek saçan. '),
