INSERT INTO `db_lugat` (`id`, `indeks`, `kelime`, `kirpilmis`, `anlam`) VALUES
(9023, 'D0', 'DİL-GİR', 'dil-gir', ' f. Kalbe sıkıntı veren gönül tutan. * Gücenmiş olan, kırgın.'),
(9024, 'D0', 'DİL-GÜŞA', 'dil-güşa', ' f. İç açan, gönül açan, kalbe ferah veren. * Türk musikisinde bir mürekkeb makam.'),
