(12380, 'F0', 'FEDEVKES', 'fedevkes', ' Arslan, esed.'),
(12381, 'F0', 'FEDFED', 'fedfed', ' (C: Fedâfid) Düz yer. * Büyük sahrâ. * Yaban. * Yüksek mekân. * Sığır buzağısı.'),
(12382, 'F0', 'FEDG', 'fedg', ' Baş yarmak.'),
(12383, 'F0', 'FEDGAM', 'fedgam', ' (C: Fedâgım) Güzel, gökçek kişi.'),
(12384, 'F0', 'FEDH', 'fedh', ' Bir kimseyi borca sokmak. * Ağır işe giriftar etmek.'),
(12385, 'F0', 'FEDÎD', 'fedid', ' Ses, savt, sada.'),
(12386, 'F0', 'FEDİR', 'fedir', ' Akılsız, ahmak kimse. * Zayıf ve âciz kimse.'),
(12387, 'F0', 'FEDK', 'fedk', ' Atmak. * Tezyin etmek, süslemek.'),
(12388, 'F0', 'FEDM', 'fedm', ' Ahmak, bön, kalın kafalı, budala. * Yaşamak. * Yaşlanmak, ihtiyarlamak. * Yorulmuş, sakil kimse.'),
