(17599, 'H0', 'HEFT-ENDAM', 'heft-endam', ' Vücudumuzda yedi organ.'),
(17600, 'H0', 'HEFT-GÂNE', 'heft-gane', ' f. Yedi türlü olan. Yedi tane.'),
(17601, 'H0', 'HEFT-HUN', 'heft-hun', ' f. Cehennemin yedi tabakası.'),
(17602, 'H0', 'HEFT-KALEM', 'heft-kalem', ' Yedi çeşit yazı. Tâlik, sülüs, tevki, muhfak, reyhanî, rik''a ve nesih.'),
(17603, 'H0', 'HEFT-KÂR', 'heft-kar', ' f. Yedi türlü iplikle dokunmuş kumaş.'),
(17604, 'H0', 'HEFT-MERD', 'heft-merd', ' f. Yedi büyükler. (Kutub, gavs, ebdâl, ahyâr, evtâd, nücebâ, nukabâ)'),
(17605, 'H0', 'HEFT-RENG', 'heft-reng', ' f. Yedi renk.'),
(17606, 'H0', 'HEFTÜM', 'heftüm', ' f. Yedinci.'),
