INSERT INTO `db_lugat` (`id`, `indeks`, `kelime`, `kirpilmis`, `anlam`) VALUES
(17619, 'H0', 'HEKK', 'hekk', ' şiddetli yağmur. * Kılıçla vurmak.'),
(17620, 'H0', 'HEKM', 'hekm', ' Halka şerle taarruz etmek.'),
