(17729, 'H0', 'HEM-GİNAN', 'hem-ginan', ' f. Bütün insanlar, bütün nev''-i beşer.'),
(17730, 'H0', 'HEM-GUŞE', 'hem-guşe', ' f. Komşu.'),
(17731, 'H0', 'HEM-HAH', 'hem-hah', ' f. Arzu ve talebleri aynı olan, aynı istekleri olan.'),
(17732, 'H0', 'HEM-HAL', 'hem-hal', ' f. Aynı halde olan. İkisi beraber.'),
(17733, 'H0', 'HEM-HANE', 'hem-hane', ' f. Bir evde oturanların beheri. Arkadaş, refik.'),
