(28419, 'L0', 'LEYK', 'leyk', ' Lâyık olmak.'),
(28420, 'L0', 'LEYKİN', 'leykin', ' f. Lâkin, ammâ, fakat.'),
(28421, 'L0', 'LEYL', 'leyl', ' Gece. (Bak: Leyle)'),
(28422, 'L0', 'LEYL-İ DİMAĞ', 'leyl-i dimağ', ' Dimağın bozukluğu. Zihnin iyi çalışmaması.'),
