(29601, 'M0', 'MAKDUD', 'makdud', ' Uzun boylu kişi.'),
(29602, 'M0', 'MAKDUH(E)', 'makduh(e)', ' (Kadh. den) Beğenilmemiş, ayıp.'),
(29603, 'M0', 'MAKDUNİS', 'makdunis', ' Maydanoz.'),
(29604, 'M0', 'MAKDUR', 'makdur', ' Güç. Kuvvet. Kudret. * Takdir olunmuş. Allah''ın takdiri. Daha evvelden takdir olunmuş.'),
(29605, 'M0', 'MAKDUR-İ BEŞER', 'makdur-i beşer', ' İnsanın yapabileceği şey.'),
(29606, 'M0', 'MAKDUR-ÜT TESLİM', 'makdur-üt teslim', ' Ele geçirilmesi mümkün olan.'),
(29607, 'M0', 'MAKDURAT', 'makdurat', ' (Makdur. C.) Takdir-i İlâhi olanlar. Güç ve kuvvet. Elden gelenler. Takdir edilenler.'),
(29608, 'M0', 'MA''KED', 'ma''ked', ' (C: Meâkıd) Akdedecek yer.'),
(29609, 'M0', 'MA''KES', 'ma''kes', ' Akis yeri. Akseden yer. (Ayna güneşin ma''kesi olduğu gibi.)'),
(29610, 'M0', 'MAKET', 'maket', ' Fr. Bina, şehir gibi eserlerin, belirli bir ölçüde küçültülmüş modeli.'),
(29611, 'M0', 'MAKH', 'makh', ' Sür''at, hız.'),
(29612, 'M0', 'MAKHUR', 'makhur', ' (Kahır. dan) Kahredilmiş. Mahvedilmiş. Bozguna uğratılmış. Mağlub. Mahkum. Allah''ın (C.C.) gazabına uğramış. Yenilmiş. Hakaret görmüş.'),
(29613, 'M0', 'MAKHUR-U KAHR-İ İLÂHÎ', 'makhur-u kahr-i ilahi', ' Allah''ın gazabına uğramış. Allah''ın kahrıyla kahrolmuş.'),
