(29645, 'M0', 'MAKR', 'makr', ' Çok acı olmak.'),
(29646, 'M0', 'MAKREBE', 'makrebe', ' Hısımlık, yakınlık. Karâbet.'),
(29647, 'M0', 'MAKREME', 'makreme', ' (Bak: Mikrame)'),
(29648, 'M0', 'MAKRU''', 'makru''', ' Okunan. Okunmuş olan.'),
(29649, 'M0', 'MAKRUF', 'makruf', ' Töhmetli kimse. * Yabana atılmış nesne.'),
