(42279, 'P0', 'PERHAŞ', 'perhaş', ' f. Savaş, harb, muharebe, cidâl, ceng. Kavga.'),
(42280, 'P0', 'PERHAŞCU(Y)', 'perhaşcu(y)', ' f. Muharib, savaşçı. Kavgacı.'),
(42281, 'P0', 'PERHİDE', 'perhide', ' f. İşaret olunmuş.'),
(42282, 'P0', 'PERHİZ', 'perhiz', ' f. Sakınmak, çekinmek. * Vücuda zararlı ve tıbben muzır; ve dinen, zevk veren şeylerden sakınmak. * Hastalıkta bazı yiyecek ve içeceklerden sakınmak.'),
(42283, 'P0', 'PERHİZKÂR', 'perhizkar', ' Perhiz eden, nefsini tutan. Zararlı şeylerden, günahlardan sakınan.'),
(42284, 'P0', 'PERHUN', 'perhun', ' f. Pergelle çizilmiş çember, dâire, halka.'),
(42285, 'P0', 'PERHÜDE', 'perhüde', ' f. Saçmasapan söz, hezeyan. * Ateşten dolayı sararmış eşyâ.'),
(42286, 'P0', 'PERİ', 'peri', ' f. Cisimleri çok lâtif ve görünmez olan hoş mahluk. * İnsana muhabbet eden, muvahhid ve müslim lâtif mahluk. *Mc: Güzel insan. Güzel kimse.'),
(42287, 'P0', 'PERİ-İ MELÂHAT', 'peri-i melahat', ' Güzellik perisi.'),
(42288, 'P0', 'PERİ-ÇİHRE', 'peri-çihre', ' f. Peri yüzlü, güzel yüzlü.'),
(42289, 'P0', 'PERİDE', 'peride', ' f. Uçmuş. *Solmuş, soluk.'),
(42290, 'P0', 'PERİDERENG', 'peridereng', ' f. Rengi uçmuş, solmuş.'),
(42291, 'P0', 'PERİ PEYKER', 'peri peyker', ' Peri yüzlü güzel.'),
(42292, 'P0', 'PERİR', 'perir', ' f. Evvelki gün.'),
(42293, 'P0', 'PERİ-RU', 'peri-ru', ' f. Peri gibi güzel yüzlü.'),
(42294, 'P0', 'PERİŞAN', 'perişan', ' f. Dağınık, karışık. * Bozuk, tertibsiz, düzensiz. * Kederli, hüzünlü, kaygılı. '),
(42295, 'P0', 'PERİŞANHÂTIR', 'perişanhatır', ' f. Dalgın, düşünceli.');
INSERT INTO `db_lugat` (`id`, `indeks`, `kelime`, `kirpilmis`, `anlam`) VALUES
(42296, 'P0', 'PERİŞANÎ', 'perişani', ' f. Perişanlık, dağınıklık. * Düzensizlik, bozgunluk. * Yoksulluk, fakirlik.'),
(42297, 'P0', 'PERİZ', 'periz', ' f. Haykırma, bağırma. Feryâd. * Su kenarlarında yetişen yeşil saz, ot.'),
(42298, 'P0', 'PERİZE', 'perize', ' f. Ateşte pişirilen ekmek. * Kırmızı altun.'),
(42299, 'P0', 'PERMER', 'permer', ' f. Ümid etme, umma, bekleme. İntizar.'),
(42300, 'P0', 'PERMUN', 'permun', ' f. Süs, bezek.'),
(42301, 'P0', 'PERNİH', 'pernih', ' f. İnce düz taş.'),
(42302, 'P0', 'PERNİYAN', 'perniyan', ' f. Nakışlı atlas. İpekten dokunmuş, bir cins işlemeli kumaş.'),
(42303, 'P0', 'PERNUN', 'pernun', ' f. İnce ve zarif dokunmuş ipek kumaş.'),
(42304, 'P0', 'PERRAN', 'perran', ' f. Uçan, uçucu.'),
(42305, 'P0', 'PERSONEL', 'personel', ' Fr. Şahsa dâir. Şahsî. * Bir işte çalışanların hepsi.'),
(42306, 'P0', 'PERTAB', 'pertab', ' f. Atılma, sıçrama. * Hız almak için geriden koşarak atılma. * Uzağa düşen ok veya başka bir şey.'),
(42307, 'P0', 'PERTEV', 'pertev', ' (Pertav) f. Ziya, ışık. * Atılma, sıçrama, hız.'),
(42308, 'P0', 'PERTEV-İ MİHR', 'pertev-i mihr', ' Güneş ışığı. Güneşin parlaklığı. '),
(42309, 'P0', 'PERTEV-FEŞAN', 'pertev-feşan', ' Işık saçan, ziya saçan.'),
(42310, 'P0', 'PERTEV-ENDÂZ', 'pertev-endaz', ' Işıklandıran, ziyâ veren, nurlandıran.'),
(42311, 'P0', 'PERTEV-SUZ', 'pertev-suz', ' Yakan ışık. Güneşe karşı tutulduğu zaman, ışıkları bir noktaya toplayan ve bu suretle ışığın değdiği yeri yakan mercek.'),
(42312, 'P0', 'PERUŞ', 'peruş', ' f. Küçük çıban, sivilce. '),
(42313, 'P0', 'PERVA', 'perva', ' f. Korku, çekinmek. * Alâka, ilgi, bağ. * Takat. * Durup dinlenmek. * Bilmek. * Vesvese. * Kayd. * Iztırab. * Terk, feragat. * Hayran, şaşmış. * Meyl, teveccüh, iltifat, kayırmak. * Gussalanmak. (L.R.)'),
(42314, 'P0', 'PERVANE', 'pervane', ' f. Fırıldak çark. * Geceleri ışığın etrafında dönen küçük kelebek. * Haberci, kılavuz.'),
(42315, 'P0', 'PERVANEGÂN', 'pervanegan', ' (Pervane. C.) Gece kelebekleri.'),
(42316, 'P0', 'PERVANEK', 'pervanek', ' f. Karakulak adı verilen bir hayvan. * Ask: Öncü, pişdâr.'),
(42317, 'P0', 'PERVAR', 'pervar', ' f. Besili, beslenmiş.'),
(42318, 'P0', 'PERVAS', 'pervas', ' f. El ile dokunup temas etme, eli ile yoklama.'),
(42319, 'P0', 'PERVAZ', 'pervaz', ' f. Kanat açmak, uçmak. Uçan, uçucu. * Nur. * Karargâh. * Saçmak. * Hücre. * Saçak. * Ayna. Dolap. * İnce, uzun tahta. * Uçan, uçucu gibi mânâlara gelerek birleşik kelimeler yapılır.'),
(42320, 'P0', 'PERVAZ-I BERDÂR', 'pervaz-ı berdar', ' Yükselip uçan. Uçarak dolaşan.'),
(42321, 'P0', 'PERVAZE', 'pervaze', ' f. Kır gezisi için hazırlanan yemek. * Altun ve gümüş yaprakların kırıntısı.'),
(42322, 'P0', 'PERVAZGÂH', 'pervazgah', ' f. Uçulacak yer. Tayyâre meydanı. Hava alanı.'),
(42323, 'P0', 'PERVER', 'perver', ' (Pervar) f. "Besleyen, yetiştiren, velinimet, koruyan" mânâsında birleşik kelimeler yapılır.'),
(42324, 'P0', 'PERVERÂN', 'perveran', ' (Perver. C.) f. Yetiştirenler, besleyenler, koruyup terbiye eden kimseler. '),
(42325, 'P0', 'PERVERDE', 'perverde', ' f. Terbiye görmüş, yetiştirilmiş, beslenmiş.'),
(42326, 'P0', 'PERVERENDE', 'perverende', ' f. Besleyen, büyüten. Besleyici, büyütücü. * Terbiye edici, yetiştirici.'),
(42327, 'P0', 'PERVERÎ', 'perveri', ' f. Büyütücülük, besleyicilik. Terbiye.'),
(42328, 'P0', 'PERVERİŞ', 'perveriş', ' f. Besleme, besleyiş. Beslenme. * Terbiye etme, yetiştirme, eğitme. Terbiye edilip yetiştirilme, eğitilme. * İlerleme, terakki.'),
(42329, 'P0', 'PERVERİŞYÂB', 'perverişyab', ' f. Beslenen. * Terbiye edilen, terbiye gören, eğitilen, yetiştirilen.'),
(42330, 'P0', 'PERVERİŞYÂFTE', 'perverişyafte', ' f. Terbiye edilmiş, büyütülmüş, yetiştirilmiş, eğitilmiş.'),
(42331, 'P0', 'PERVİN', 'pervin', ' f. Ülker denilen yedi yıldızın tamamı.'),
(42332, 'P0', 'PERVİZ', 'perviz', ' f. Üstün, galib, muzaffer. * Elek. Süzgeç. * Güzellik. * Balık. * Cilve. * Tar: İran Hükümdarı Husrev''in lâkabı.'),
(42333, 'P0', 'PERVİZ-İ FELEK', 'perviz-i felek', ' Güneş, şems.  '),
(42334, 'P0', 'PERVİZEN', 'pervizen', ' f. Elek, kalbur.'),
(42335, 'P0', 'PES', 'pes', ' f. Arka, art, geri. * Öyle ise, imdi...'),
(42336, 'P0', 'PES-İ DİVÂR', 'pes-i divar', ' Duvarın arkası.'),
(42337, 'P0', 'PES-İ PERDE', 'pes-i perde', ' Perde arkası.'),
(42338, 'P0', 'PES Ü PİŞ', 'pes ü piş', ' Arka ve ön.'),
(42339, 'P0', 'PESADET', 'pesadet', ' f. Veresiye alışveriş.'),
(42340, 'P0', 'PESAVEND', 'pesavend', ' f. Kafiye.'),
(42341, 'P0', 'PESEND', 'pesend', ' f. Beğenmek, kabul eylemek. Beğenici. Muvâfık.'),
(42342, 'P0', 'PESENDÂNE', 'pesendane', ' Beğenecek yolda, beğenmek suretiyle.'),
(42343, 'P0', 'PESENDİDE', 'pesendide', ' f. Beğenilmiş, seçilmiş, müntehab.'),
(42344, 'P0', 'PESİN', 'pesin', ' f. Sonraki, gerideki, en son.'),
(42345, 'P0', 'PESMANDE', 'pesmande', ' f. Geri kalmış, geride bulunan, bâkiye. * Artmış, artık.'),
(42346, 'P0', 'PESMANDE-HOR', 'pesmande-hor', ' f. Artık yiyen.'),
(42347, 'P0', 'PESPERDE', 'pesperde', ' f. Perde arkası, gizli iş.'),
(42348, 'P0', 'PESREV', 'pesrev', ' f. Arkadan gelen. * Uşak, hizmetçi.'),
(42349, 'P0', 'PEST', 'pest', ' f. Alçak, aşağı. Hafif, yavaş ses. * Sesi galiz, kalın ve korkunç olan.'),
(42350, 'P0', 'PESTBAHT', 'pestbaht', ' f. Talihsiz. Bahtı fenâ olan.'),
(42351, 'P0', 'PESTÎ', 'pesti', ' f. Alçaklık, âdilik, zillet.'),
(42352, 'P0', 'PESTPAYE', 'pestpaye', ' (C.: Pestpayegân) Payesi, derecesi aşağı olan, âdi. Alçak. Bayağı. Pespaye.'),
(42353, 'P0', 'PESTPERDE', 'pestperde', ' f. Alçak ve hafif sesle.'),
(42354, 'P0', 'PESTSADA', 'pestsada', ' f. Hafif ses.'),
(42355, 'P0', 'PEŞE', 'peşe', ' (Bak: Peşşe)'),
(42356, 'P0', 'PEŞİMAN', 'peşiman', ' f. Pişman. Nâdim.'),
(42357, 'P0', 'PEŞİMANÎ', 'peşimani', ' f. Pişmanlık, nedamet.'),
(42358, 'P0', 'PEŞİN', 'peşin', ' f. Nakdî para. * Önceden, önce.'),
(42359, 'P0', 'PEŞİNÂT', 'peşinat', ' f. Peşin verilen paralar.'),
(42360, 'P0', 'PEŞİZ', 'peşiz', ' (Peşize) f. Akçe, mangır. Pul. * Balık pulu.'),
(42361, 'P0', 'PEŞKEŞ', 'peşkeş', ' (Pişkeş) f. Başkasının malını birine bağışlamak. Verilmemesi lâzım olan şeyi başkasına vermek. Karşılıksız vermek.(Bir şeyde mehâsin ve şeref hâsıl oldukça, havassa peşkeş ederler; seyyiât olsa, avâma taksim ederler! M.)'),
(42362, 'P0', 'PEŞLENG', 'peşleng', ' f. Geri kalan, geri kalmış.'),
(42363, 'P0', 'PEŞM', 'peşm', ' f. Yapağı, yün. * Keten helvası.'),
(42364, 'P0', 'PEŞMİN', 'peşmin', ' (Peşmine) f. Yünden yapılmış. Yapağıdan yapılma. * Sâde ve süssüz elbise.'),
(42365, 'P0', 'PEŞREV', 'peşrev', ' f. (Aslı: Pişrev) Önde giden. * Türk müziğinde bir saz eseri. * Güreşten önce pehlivanların ellerini birbirine veya dizlerine çarparak ve biraz sıçrayarak yaptıkları oyun. * Bir çeşit ok.'),
(42366, 'P0', 'PEŞŞE', 'peşşe', ' f. Sivrisinek.'),
(42367, 'P0', 'PEŞŞEGİR', 'peşşegir', ' f. Sinek avlıyan. * Mc: İşsiz güçsüz, boş gezen kimse.'),
(42368, 'P0', 'PETER', 'peter', ' f. Düz maden levha.'),
(42369, 'P0', 'PETGİR', 'petgir', ' f. Kıl elek.'),
(42370, 'P0', 'PEY', 'pey', ' f. İz, işaret, nişan. * Ard, arka, akab.'),
(42371, 'P0', 'PEYAM', 'peyam', ' (Peygam) f. Haber.'),
(42372, 'P0', 'PEYAM-I HASRET', 'peyam-ı hasret', ' Hasret, özleyiş haberi.'),
(42373, 'P0', 'PEYAM-ÂVER', 'peyam-aver', ' (C.: Peyamâverân) f. Haber getiren.'),
(42374, 'P0', 'PEYAM-BER', 'peyam-ber', ' f. Haber getiren. Peygamber.'),
(42375, 'P0', 'PEY-A-PEY', 'pey-a-pey', ' f. Birbiri ardınca, birbirinin arkasından. * Azar azar, tedricen, peyderpey.'),
(42376, 'P0', 'PEYDA', 'peyda', ' f. Mevcud, var olan, açık, âşikâr, meydanda olan.'),
(42377, 'P0', 'PEY-DER-PEY', 'pey-der-pey', ' f. Birbiri ardınca. Yavaş yavaş, azar azar.'),
(42378, 'P0', 'PEYEMRES', 'peyemres', ' f. Haber getiren, haber ulaştıran, haberci.'),
(42379, 'P0', 'PEY-ENDER-PEY', 'pey-ender-pey', ' f. Ardısıra, arka arkaya, durmadan. Azar azar.'),
(42380, 'P0', 'PEYGAM', 'peygam', ' (Bak: Peyam)'),
(42381, 'P0', 'PEYGAMAVER', 'peygamaver', ' (Peygam-âver) f. Haber getiren, haberci.'),
(42382, 'P0', 'PEYGAMBER', 'peygamber', ' (Peyamber) f. Allah''tan haber getiren. Allah''ı, âhireti, zararlı ve faydalı şeyleri tanıtan. Nebi. (Bak: Mefhar-ı kâinat, Muhammed (A.S.M.), Nübüvvet, Resül)'),
(42383, 'P0', 'PEYGAMBERÂN', 'peygamberan', ' (Peygamber. C.) Peygamberler.'),
(42384, 'P0', 'PEYGAMBERÎ', 'peygamberi', ' f. Peygamberlik. * Peygamberle alâkalı.'),
(42385, 'P0', 'PEYGAR', 'peygar', ' f. Savaş, harb, muharebe, cidal. Kavga.'),
(42386, 'P0', 'PEYGARE', 'peygare', ' f. İftira.'),
(42387, 'P0', 'PEYGULE', 'peygule', ' f. Köşe, bucak.'),
(42388, 'P0', 'PEYGULE-İ NİSYAN', 'peygule-i nisyan', ' Unutulma köşesi.'),
(42389, 'P0', 'PEYGULEGÜZİN', 'peygulegüzin', ' Bir köşede oturan. Köşeye çekilmiş olan.'),
(42390, 'P0', 'PEYGUN', 'peygun', ' f. And, şart, ahd, peyman.'),
(42391, 'P0', 'PEYK', 'peyk', ' f. Bir şeyin etrafında, ona tabi olarak dönen. Seyyare. * Haber ve mektup getirip götüren.'),
(42392, 'P0', 'PEYK-İ FELEK', 'peyk-i felek', ' Ay. Dünyanın etrafında dönen ay. Dünyanın peyki. '),
(42393, 'P0', 'PEYKAN', 'peykan', ' Okun ucundaki sivri demir.'),
(42394, 'P0', 'PEYKE', 'peyke', ' f. Tahta sedir.'),
(42395, 'P0', 'PEYKER', 'peyker', ' f. Yüz, çehre, surat.'),
(42396, 'P0', 'PEYM', 'peym', ' f. Haber. '),
(42397, 'P0', 'PEYMA', 'peyma', ' f. Ölçen, ölçücü.'),
(42398, 'P0', 'PEYMAN', 'peyman', ' f. And, yemin, muahede, ahitleşmek.(Cihet-ül vahdet-i ittihadımız, tevhiddir. Peyman ve yeminimiz, imandır. Madem ki muvahhidiz, müttehidiz. Her bir mü''min ilâ-yı Kelimetullah ile mükelleftir. Bu zamanda bunun mühim bir sebebi maddeten terakki etmektir. H.Ş.)'),
(42399, 'P0', 'PEYMANE', 'peymane', ' f. Büyük kadeh. * Ölçek, kile. * Şarap bardağı.'),
(42400, 'P0', 'PEYMANEKEŞ', 'peymanekeş', ' f. İçki içen.'),
(42401, 'P0', 'PEYMANE-ŞİKEST', 'peymane-şikest', ' f. Kadehi kırık.'),
(42402, 'P0', 'PEYMAN-ŞİKEN', 'peyman-şiken', ' (Peyman-şikân) Yemin bozan, ahdini yerine getirmeyen.'),
(42403, 'P0', 'PEYMAY', 'peymay', ' f. Tartıcı, ölçücü.'),
(42404, 'P0', 'PEYMUDE', 'peymude', ' f. Ölçülmüş.'),
(42405, 'P0', 'PEYREV', 'peyrev', ' f. Ardı sıra giden, tâbi olan, izinden giden, uyan.'),
(42406, 'P0', 'PEYSİPER', 'peysiper', ' f. Çiğnenmiş, ayak altında kalmış.'),
(42407, 'P0', 'PEYUG', 'peyug', ' (C.: Peyugân) f. Gelin.'),
(42408, 'P0', 'PEYUGAN', 'peyugan', ' (Peyug. C.) Gelinler.'),
(42409, 'P0', 'PEYVEND', 'peyvend', ' f. Ulaşma, varma, vasıl olma. * Bağ, alâka.'),
(42410, 'P0', 'PEYVEST', 'peyvest', ' f. Ulaşma, vasıl olma, kavuşma.'),
(42411, 'P0', 'PEYVESTE', 'peyveste', ' f. Her zaman, dâima. * Ulaşmış, ermiş. * Bitişik, muttasıl.'),
(42412, 'P0', 'PEYVESTEGÎ', 'peyvestegi', ' f. Bitişme, ulaşma, bitişiklik.'),
(42413, 'P0', 'PEZİR', 'pezir', ' f. Kabul eden, olan, olabilen. * "Söz dinleyici, emir tutan" mânasında birleşik kelimeler yapılır.'),
(42414, 'P0', 'PEZİRA', 'pezira', ' f. Kabul eden.'),
(42415, 'P0', 'PEZİRAY-HİTAM', 'peziray-hitam', ' Sona eren, biten, hitam bulan.'),
(42416, 'P0', 'PEZİRE', 'pezire', ' f. Karşılama, karşılayış.'),
(42417, 'P0', 'PEZİRİŞ', 'peziriş', ' f. Kabul edilmiş. Kabul ediş. '),
(42418, 'P0', 'PILAÇKA', 'pılaçka', ' (Arnavutça) Tar: Muharebede ve yağmada alınan eşya, çapul.'),
(42419, 'P0', 'PIRLANTA', 'pırlanta', ' İtl. Çok tıraş edilmiş, foyasız parlak elmas. Taşı pırlanta olan.'),
(42420, 'P0', 'PİÇ', 'piç', ' f. Büklüm, kıvrım, dolaşık. * Nesebi gayr-ı sahih olan, gayr-ı meşru münâsebetten doğan çocuk. * Aslına benzemiyen. * Ağacın kökünden biten sürgün. Aşılanmamış ağaç. * Sarmaşık. * Vida.'),
(42421, 'P0', 'PİÇAN', 'piçan', ' f. Büklüm büklüm, kıvrım kıvrım olan.'),
(42422, 'P0', 'PİÇ-A-PİÇ', 'piç-a-piç', ' f. Karma karış, pek dolaşık, kıvrım kıvrım.'),
(42423, 'P0', 'PİÇİDE', 'piçide', ' f. Karışmış, bükülmüş, kıvrılmış. '),
(42424, 'P0', 'PİÇİDEMUY', 'piçidemuy', ' f. Saçı kıvrılmış.'),
(42425, 'P0', 'PİÇİŞ', 'piçiş', ' f. Büklüm, kıvrım.'),
(42426, 'P0', 'PİÇ-PA', 'piç-pa', ' f. Yengeç.'),
(42427, 'P0', 'PİÇTAB', 'piçtab', ' f. Sıkıntı, telâş. * Şaşkınlık.'),
(42428, 'P0', 'PİÇ Ü TAB', 'piç ü tab', ' Iztırab ve sıkıntı. '),
(42429, 'P0', 'PİH', 'pih', ' f. İçyağı. Şahm.'),
(42430, 'P0', 'PİH', 'pih', ' f. Göz çapağı.'),
(42431, 'P0', 'PİH-SUZ', 'pih-suz', ' f. "Yağ yakıcı": Toprak kandil. '),
(42432, 'P0', 'PİJUH', 'pijuh', ' (Bak: Pejuh)'),
(42433, 'P0', 'PİL', 'pil', ' f. Topuk, ökçe. * Çelik çomak oyunu. * Çadır eteği tutturmada kullanılan küçük ağaç değnekler.'),
(42434, 'P0', 'PİL', 'pil', ' f. Fil.'),
(42435, 'P0', 'PİL-BÂN', 'pil-ban', ' f. Fil besleyen, filci.'),
(42436, 'P0', 'PİLE', 'pile', ' f. İpek kozası. İpek.'),
(42437, 'P0', 'PİLESTE', 'pileste', ' f. Fildişi.'),
(42438, 'P0', 'PİL-TEN', 'pil-ten', ' Fil gibi iri, fil vücutlu.'),
(42439, 'P0', 'PİLVAYE', 'pilvaye', ' f. Kırlangıç.'),
(42440, 'P0', 'PİL-ZUR', 'pil-zur', ' f. Fil gibi kuvvetli, fil kuvvetinde.'),
(42441, 'P0', 'PİNDAR', 'pindar', ' Sanma, zannetme. * Böbürlenme.'),
(42442, 'P0', 'PİNE', 'pine', ' f. Yama.'),
