(45330, 'S0', 'SAYİL', 'sayil', ' Alında olan beyazlık. * Burun kamışı.'),
(45331, 'S0', 'SAYİME', 'sayime', ' (C.: Sevâyim) Yılın ekserinde yabanda yürüyen davar.'),
(45332, 'S0', 'SAYİR', 'sayir', ' Bakan, seyreden. Seyredici.'),
(45333, 'S0', 'SAYİS', 'sayis', ' (Siyaset. den) At uşağı, seyis. Koyun güdücü.'),
(45334, 'S0', 'SAYİS-HANE', 'sayis-hane', ' f. Üzerine yük yüklenip yolcunun da bindiği hayvan.'),
(45335, 'S0', 'SAYK', 'sayk', ' (Bak: Sıyk)'),
(45336, 'S0', 'SAYKAL', 'saykal', ' Cilâ. Cilâ yapan âlet. Parlatan. * Kılıç bileyen.'),
(45337, 'S0', 'SAYKAL VURMAK', 'saykal vurmak', ' Cilâ vurmak, parlatmak.'),
(45338, 'S0', 'SAYKALZEDE', 'saykalzede', ' f. Cilâlı. Cilâlanmış.'),
(45339, 'S0', 'SAYKALZEN', 'saykalzen', ' f. Yaldızcı.'),
(45340, 'S0', 'SAYLEM', 'saylem', ' Zorluk, meşakkat.'),
(45341, 'S0', 'SAYREF', 'sayref', ' (C.: Seyârif) Sarraf. * İşini, çıkarını, hesabını bilir, kurnaz kimse.'),
(45342, 'S0', 'SAYREFÎ', 'sayrefi', ' (C.: Sayârife) Sarraf.'),
(45343, 'S0', 'SAYREM', 'sayrem', ' Bir lokma yemek.'),
