(47622, 'S0', 'SURET-ÜL ASR', 'suret-ül asr', ' Kur''an-ı Kerim''in yüzüçüncü suresi.'),
(47623, 'S1', 'ŞAAB', 'şaab', ' Ayrılmak. * Yarmak.'),
(47624, 'S1', 'ŞA''AR', 'şa''ar', ' Kıl büken.'),
(47625, 'S1', 'ŞAAR', 'şaar', ' Ağaç, şecer.'),
(47626, 'S1', 'ŞAB', 'şab', ' (Bak: şap)'),
(47627, 'S1', 'ŞA''B', 'şa''b', ' (C.: şuub) Tâife, cemaat. Kabile.'),
(47628, 'S1', 'ŞA''B', 'şa''b', ' Ayrılmak. Dağılmak. * Islah etmek, düzeltmek. * Helâk etmek. * Kırmak.'),
(47629, 'S1', 'ŞA''BAN', 'şa''ban', ' (Şâbân) Arabi ayların sekizincisi. Mübârek Şuhur-u selâsenin (Üç ayların) ikincisi.'),
(47630, 'S1', 'ŞABAŞ', 'şabaş', ' f. Alkış etme, alkışlama. Aferin deme. Bir hareketi güzel bulmaktan dolayı alkışlamak veya hediye vermek.'),
(47631, 'S1', 'ŞABAŞHÂN', 'şabaşhan', ' f. Beğenip alkışlayan.'),
(47632, 'S1', 'ŞABB', 'şabb', ' Genç, delikanlı, yiğit.'),
(47633, 'S1', 'ŞABB-I EMRED', 'şabb-ı emred', ' Bıyığı, sakalı henüz çıkmış delikanlı.'),
(47634, 'S1', 'ŞABBE', 'şabbe', ' Genç kadın.'),
(47635, 'S1', 'ŞA''BEZE', 'şa''beze', ' El çabukluğu.'),
(47636, 'S1', 'ŞAB-HANE', 'şab-hane', ' f. Şap çıkarılan yer.'),
(47637, 'S1', 'ŞABİH', 'şabih', ' Misil olan, nazir, benzeyen.'),
(47638, 'S1', 'ŞABUB', 'şabub', ' (C.: Şeabib) Sağanak yağmur.'),
(47639, 'S1', 'ŞACİNE', 'şacine', ' (C.: Şevâcin) Ağaçlı ve meşeli dere.'),
(47640, 'S1', 'ŞACİR', 'şacir', ' Ayak altında ızdırap çekmek.'),
