(49454, 'T0', 'TACDARÎ', 'tacdari', ' f. Padişahlık, hükümdarlık.'),
(49455, 'T0', 'TACEN', 'tacen', ' Tava. * Büyük kiremit.'),
(49456, 'T0', 'TACGAH', 'tacgah', ' f. Hükümet merkezi.'),
