(49469, 'T0', 'TADABBÜB', 'tadabbüb', ' Besililik. Semizlik.'),
(49470, 'T0', 'TADABBÜR', 'tadabbür', ' Muhkem olmak, sağlamlaşmak. * Bağlanmak.'),
(49471, 'T0', 'TADACCU''', 'tadaccu''', ' Üşenme, gevşek davranma.'),
(49472, 'T0', 'TADACCUR', 'tadaccur', ' (Ducret. den) Sıkılma, sıkıntı, iç sıkılması.'),
(49473, 'T0', 'TADACÜM', 'tadacüm', ' İhtilâf. Anlaşmazlık. * Eğrilik.'),
(49474, 'T0', 'TA''DAD', 'ta''dad', ' Sayı saymak. Sayıp dökmek. Birer birer söylemek. Sıralamak.'),
(49475, 'T0', 'TADADD', 'tadadd', ' Birbirine düşmanlık etmek.'),
(49476, 'T0', 'TADA''DU', 'tada''du', ' Alçak gönüllülük gösterme. * Viran olma. * Aklını kaybetme.'),
(49477, 'T0', 'TADAFÜR', 'tadafür', ' Bir yere toplanmak. * Yardım etmek, muâvenet etmek.'),
(49478, 'T0', 'TADAGUN', 'tadagun', ' Birbirini istemeyip garaz edişmek.'),
(49479, 'T0', 'TADAHDUH', 'tadahduh', ' şarap dökülmek.'),
(49480, 'T0', 'TADAHHUM', 'tadahhum', ' Ağızla tutmak.'),
(49481, 'T0', 'TADAHUK', 'tadahuk', ' Gülüşmek.'),
(49482, 'T0', 'TADALLU''', 'tadallu''', ' Dolmak. * Suya kanmak.'),
(49483, 'T0', 'TADALLÜL', 'tadallül', ' Gedik olmak.'),
(49484, 'T0', 'TADAMM', 'tadamm', ' Bir yere cem''olmak, toplanmak.'),
(49485, 'T0', 'TADAMMUH', 'tadammuh', ' Bulaşmak.'),
(49486, 'T0', 'TADAMMUN', 'tadammun', ' (Bak: Tazammun)'),
(49487, 'T0', 'TADAMMÜD', 'tadammüd', ' Yaraya merhem sürüp bezle bağlamak.'),
(49488, 'T0', 'TADARR', 'tadarr', ' Birbirine zarar etmek.'),
(49489, 'T0', 'TADARRU''', 'tadarru''', ' İnlemek.'),
(49490, 'T0', 'TADARRUS', 'tadarrus', ' Diş kamaşması.'),
(49491, 'T0', 'TADARUG', 'tadarug', ' Sıkılmak.'),
(49492, 'T0', 'TADARUT', 'tadarut', ' Yellenmek.'),
(49493, 'T0', 'TADAUF', 'tadauf', ' Kat kat olmak.'),
(49494, 'T0', 'TADAVVU''', 'tadavvu''', ' Kokmak.'),
(49495, 'T0', 'TADAVVÜC', 'tadavvüc', ' Derenin dar ve kısık yerleri çok olmak.'),
(49496, 'T0', 'TADAVVÜR', 'tadavvür', ' Çağırmak, bağırmak, feryad etmek. * İnlemek. * Açlık.'),
(49497, 'T0', 'TADBAS', 'tadbas', ' Sabun.'),
(49498, 'T0', 'TADBİB', 'tadbib', ' Semiz etmek, beslemek. * Geri koymak.'),
(49499, 'T0', 'TADBİR', 'tadbir', ' Tabiatı muhkem olmak. * Nameyi iplikle bağlamak.'),
(49500, 'T0', 'TADBİS', 'tadbis', ' Sabun.'),
(49501, 'T0', 'TADCİ''', 'tadci''', ' Süstlük etmek, zayıflamak.'),
(49502, 'T0', 'TADCİR', 'tadcir', ' Can sıkma, yürek daraltma.'),
(49503, 'T0', 'TADFİR', 'tadfir', ' Saç örmek. * Yürürken çok sallanmak. * Çok çalışmak.'),
(49504, 'T0', 'TADHİK', 'tadhik', ' Güldürmek.'),
(49505, 'T0', 'TADHİYE', 'tadhiye', ' Kurban kesmek.'),
(49506, 'T0', 'TADÎ', 'tadi', ' Âdet.'),
(49507, 'T0', 'TA''DİD', 'ta''did', ' Sayma. * Hazırlanma, hazırlanılma.'),
(49508, 'T0', 'TA''DİD', 'ta''did', ' Mübâlağa ile ısırmak.'),
(49509, 'T0', 'TAD''İF', 'tad''if', ' İki kat yapmak. * Çoğaltmak. * Zayıflatmak.'),
(49510, 'T0', 'TA''DİL', 'ta''dil', ' (Adl. den) Aslına zarar vermeden değiştirmek. Tebdil etmek.* Hafifletmek. * Doğrulaştırmak. Vasat hale koymak.'),
(49511, 'T0', 'TA''DİL-İ ERKÂN', 'ta''dil-i erkan', ' Fık: Namazın bütün rükünleri, esaslarını usulüne uygunca yerine getirerek ve namazın tertib ve düzeninin hakkını vererek kılmak. Meselâ : "Secdeyi sükunetle yerine getirmek ve iki secde arasında "Sübhânallah" diyecek kadar doğrularak oturmak. Kıyamda ve rüku''dan sonraki kıyamda sükunet üzere olmak ve namazın bütün duâlarını dikkatle okumak. Namazın her rüknünü yerine getirmek, acele ile kılmamak" gibi.'),
(49512, 'T0', 'TA''DİL', 'ta''dil', ' Darlık vermek. * Veledi karnında büyük olup doğurması güç olmak.'),
(49513, 'T0', 'TA''DİLAT', 'ta''dilat', ' Değişiklikler, doğrultmalar, değiştirmeler, tebdil etmeler.'),
(49514, 'T0', 'TA''DİYE', 'ta''diye', ' Tecavüz ettirmek, geçirmek. * Gr: Bir fiili müteaddi hâle koymak. Meselâ: "Gülmek. den: Güldürmek. Ölmek. den: Öldürmek" gibi.'),
(49515, 'T0', 'TA''DİYE', 'ta''diye', ' Dağılmak. * Koyunun yününü kırkmak.'),
(49516, 'T0', 'TADLİ''', 'tadli''', ' Kavunu dilim dilim kesmek.'),
(49517, 'T0', 'TADLİL', 'tadlil', ' Doğru yoldan sapıtmak. * Azdırmak, ayartmak. Günah işletmek. Dalâlete saptırmak.'),
(49518, 'T0', 'TADLİL-İ GAYR', 'tadlil-i gayr', ' Başkalarını dalâlete nisbet etmek. Sapıklığına hükmetmek.'),
(49519, 'T0', 'TADMİD', 'tadmid', ' Başına veya koluna merhem sürüp bez bağlamak.'),
(49520, 'T0', 'TADMİR', 'tadmir', ' Atı semirince yulaf verip beslemek. (Kırk günde olur.) * İnce belli yapmak.'),
(49521, 'T0', 'TADRİ''', 'tadri''', ' Yakın etmek, yaklaştırmak.'),
(49522, 'T0', 'TADRİB', 'tadrib', ' Kebabı iyi pişirmek. * Avazı güzelce çekip nağmelendirmek. (Buna "tadrib-i fi-s-savt" denir).'),
(49523, 'T0', 'TADRİC', 'tadric', ' Kanatmak.'),
(49524, 'T0', 'TADRİM', 'tadrim', ' Ateş yakmak.'),
(49525, 'T0', 'TADRİS', 'tadris', ' Tecrübe görmüş olma.'),
(49526, 'T0', 'TADRİYE', 'tadriye', ' Kandırmak. * Çok hırslı olmak.'),
(49527, 'T0', 'TA''DUD', 'ta''dud', ' Çok tatlı kara hurma.'),
(49528, 'T0', 'TADYİ''', 'tadyi''', ' Zâyi etmek, kaybetmek.'),
(49529, 'T0', 'TADYİF', 'tadyif', ' Konuk almak.TAF'' : Ateşin sönmesi.'),
(49530, 'T0', 'TAFA', 'tafa', ' İnce bulut.'),
(49531, 'T0', 'TAFADDUL', 'tafaddul', ' Faziletlilik iddia etmek, üstünlük iddiasında bulunmak.'),
(49532, 'T0', 'TAFADUL', 'tafadul', ' Fazilet göstermek.'),
(49533, 'T0', 'TAFAF', 'tafaf', ' Dolu olmak.'),
(49534, 'T0', 'TAFA''FU''', 'tafa''fu''', ' Evmek, acele etmek.'),
(49535, 'T0', 'TAFASSİ', 'tafassi', ' Halâs olmak, kurtulmak.'),
(49536, 'T0', 'TAFATTUN', 'tafattun', ' (Fatanet. den) Anlama, farkına varma, akıl erdirme.'),
(49537, 'T0', 'TAFATTUR', 'tafattur', ' Yarılma, ayrılma, açılma.'),
(49538, 'T0', 'TAFAZZU''', 'tafazzu''', ' Kesilmek.'),
(49539, 'T0', 'TAFAZZUH', 'tafazzuh', ' Rezillik, kepazelik. Rüsvaylık.'),
(49540, 'T0', 'TAFAZZUL', 'tafazzul', ' (Fazl. dan) Üstünlük taslama.'),
(49541, 'T0', 'TAFDİH', 'tafdih', ' (Fedahat. dan) Rezil etme. Kötülüklerini yayarak adını kötüleme.'),
(49542, 'T0', 'TAFDİL', 'tafdil', ' Bir şeyi üstün kılmak. Birisini ötekisinden mühim görmek. * Gr: Bir şeyi "en üstün, daha üstün daha çok, en iyi, daha iyi" gibi mânâ ifâde etmesi için mukayese ve üstünlük gösteren ismini söylemek ki, buna "ism-i tafdil" denir. Ef''al () vezninde; efdal (daha faziletli), ekber; (en büyük), ahsen; (en güzel, daha güzel) gibi. Türkçede; kelimenin başına daha, en, pek, pek çok gibi kelimeler getirilerek yapılır. Farsçada ise; kelimenin sonuna "ter, terin" gibi ekler getirilir. Bed. den; bedter, bedterin (daha kötü, en kötü) gibi.'),
(49543, 'T0', 'TAFE', 'tafe', ' Yağmur. * Karanlık. * Güneşin, batmaya yaklaşması.'),
(49544, 'T0', 'TAFES', 'tafes', ' Kir, necis.'),
(49545, 'T0', 'TAFF', 'taff', ' Tamam alıp eksik vermek.'),
(49546, 'T0', 'TAFH', 'tafh', ' Kaldırmak. * Dolu olmak.'),
(49547, 'T0', 'TAFİ', 'tafi', ' Her nesnenin üstüne gelen. * Hâriç, dış.'),
(49548, 'T0', 'TAFİF', 'tafif', ' Az, kalil.'),
(49549, 'T0', 'TAFİH', 'tafih', ' Dolu, mümteli.'),
(49550, 'T0', 'TA''FİR', 'ta''fir', ' Tozlu ve topraklı yapmak. * Ağartmak, beyazlatmak. * Kirletmek. Mülevves etmek. * Oğlan kaçsın diye kadının, emziğine toprak sürmesi. * Güneşte et kurutmak. (O kurumuş ete "afir" derler.)'),
(49551, 'T0', 'TAFK', 'tafk', ' (Tafak) Bir işe başlamak, mülâzemet etmek, başlayıp devamda sebat etmek.'),
(49552, 'T0', 'TAFN', 'tafn', ' Ölüm, mevt. * Haps.'),
(49553, 'T0', 'TAFR (TUFUR)', 'tafr (tufur)', ' Yukarı sıçramak. Kalkmak.'),
(49554, 'T0', 'TAFRA', 'tafra', ' Yukarıya sıçrama atlama. * Yukarıdan atıp tutma. * İlmiye sınıfında rütbe ve derece alma.'),
(49555, 'T0', 'TAFS (TUFUS)', 'tafs (tufus)', ' Ölüm, mevt.'),
(49556, 'T0', 'TAFSİL', 'tafsil', ' Etraflı olarak bildirmek. * Açıklamak, şerh ve beyan etmek. İzah etmek.'),
(49557, 'T0', 'TAFSİLÂT', 'tafsilat', ' (Tafsil. C.) Açıklamalar, izahlar.'),
(49558, 'T0', 'TAFSİLEN', 'tafsilen', ' Uzun uzadıya, tafsilâtlı olarak.');
INSERT INTO `db_lugat` (`id`, `indeks`, `kelime`, `kirpilmis`, `anlam`) VALUES
(49559, 'T0', 'TAFSİYE', 'tafsiye', ' Halâs etmek, kurtarmak.'),
(49560, 'T0', 'TAFŞELE', 'tafşele', ' Kaygana aşı. * Baklava.'),
(49561, 'T0', 'TAFTAF', 'taftaf', ' Yumuşak taze ot. * Ağacın çevresi.'),
(49562, 'T0', 'TAFTAFE', 'taftafe', ' (C.: Tavâtıf) Böğür, hâsıra.'),
(49563, 'T0', 'TAFTHANE', 'tafthane', ' f. Matbaa. Basımevi.'),
(49564, 'T0', 'TAFTİN', 'taftin', ' (Fatanet. den) Anlatma, akıl erdirtme.'),
(49565, 'T0', 'TAFTİR', 'taftir', ' Orucunu açmak.'),
(49566, 'T0', 'TAFV', 'tafv', ' Bir şeyin batmayıp su üzerinde kalması. * Ağaç üzerinde yaprağın belirmesi. * Bir işe girmek. * Hayvanın tepe üzerine çıkması. * Ceylânın koşması.'),
(49567, 'T0', 'TAFZİH', 'tafzih', ' (C.: Tafzihât) Rezil etme.'),
(49568, 'T0', 'TAFZİZ', 'tafziz', ' Gümüş kaplama, gümüşleme.'),
(49569, 'T0', 'TAGADDİ', 'tagaddi', ' (Gıda. dan) Gıdalanmak, beslenmek. * Sabah yemeği.'),
(49570, 'T0', 'TAGADDİYÂT', 'tagaddiyat', ' (Tagaddi. C.) Gıdalanmalar, beslenmeler.'),
(49571, 'T0', 'TAGALLÜB', 'tagallüb', ' Zorbalık. * Hilâf-ı hak olarak musallat olmak. İstilâ etmek. * Üstün gelmek.'),
(49572, 'T0', 'TAGALLÜBÂT', 'tagallübat', ' (Tagallüb. C.) Zorbalıklar, tahakkümler.'),
(49573, 'T0', 'TAGAME', 'tagame', ' (C.: Tıgâm) Hor ve zelil kimse. * Ufacık kuşlar.'),
(49574, 'T0', 'TAGAMGUM', 'tagamgum', ' Anlaşılmaz söz.'),
(49575, 'T0', 'TAGANNİ', 'taganni', ' (Gınâ. dan) Muhtaç olmamak. * Kâfi bulmak. * Zengin olmak. * Şarkı söylemek. Bir ibareyi makamla okumak. * Bir şâirin birisini medih veya hicvetmesi.'),
(49576, 'T0', 'TAGANNÜM', 'tagannüm', ' (Bak: Tegannüm)'),
(49577, 'T0', 'TAGAŞŞİ', 'tagaşşi', ' (Gışâ. dan) Bürünmek, örtünmek.'),
(49578, 'T0', 'TAGAVVÜL', 'tagavvül', ' Renkten renge girmek. Rengini değiştirmek.'),
(49579, 'T0', 'TAGAYYÜB', 'tagayyüb', ' (Gayb. dan) Gözden kaybolma, görünmeme.'),
(49580, 'T0', 'TAGAYYÜR', 'tagayyür', ' Değişmek. Başkalaşmak. * Bozulmak. Renk değiştirmek. * Kokmak.(Tagayyür ve tebeddül; hudûsten ve tekemmül etmek için tazelenmekten ve ihtiyaçtan ve maddilikten ve imkândan ileri geliyor. Zât-ı Akdes ise; hem kadîm, hem her cihetçe kemal-i mutlakta, hem istiğna-yı mutlakta, hem maddeden mücerred; hem Vâcib-ül-Vücud olduğundan; elbette tagayyür ve tebeddülü muhaldir, mümkün değildir. L.)'),
(49581, 'T0', 'TAGAYYÜRAT', 'tagayyürat', ' (Tagayyür. C.) Başkalaşmalar, bozulmalar. Değişmeler.'),
(49582, 'T0', 'TAGAYYÜZ', 'tagayyüz', ' Gayzlanma, kin besleme. * Kızma, hiddete gelme.'),
(49583, 'T0', 'TAGAYYÜZAT', 'tagayyüzat', ' Hiddetlenmeler. Kızmalar.'),
(49584, 'T0', 'TAGAZZİ', 'tagazzi', ' (C.: Tagazziyât) Gıdalanma, beslenme.'),
(49585, 'T0', 'TAGBİR', 'tagbir', ' (C.: Tagbirât) (Gubar. dan) Toza bulaştırma. * Gücendirme, muğber etme.'),
(49586, 'T0', 'TAGDİYE', 'tagdiye', ' Sabah yemeği yedirmek. * Gıdalandırmak, beslemek. Beslenmek.'),
(49587, 'T0', 'TAGFİL', 'tagfil', ' (C.: Tagfilât) (Gaflet. den) Gafil avlama veya gafil avlanma.'),
(49588, 'T0', 'TAGIYE', 'tagıye', ' Salak, kibirli ve inatçı adam. * Yıldırım.'),
(49589, 'T0', 'TAGİ', 'tagi', ' (Tagy) (Tuğyan. dan) Azgın. Azmış. Asi. Mütekebbir ve ahmak olan. * Dindar olmayan padişah.'),
(49590, 'T0', 'TAGLİB', 'taglib', ' Edb: Bir alâkadan dolayı bir kelimeyi, başka bir mânayı da içine alacak şekilde kullanma. Baba ile anaya "Ebeveyn" denilmesi gibi.'),
(49591, 'T0', 'TAGLİF', 'taglif', ' (Gılaf. dan) Kınına koyma, kılıfına sokma. * İyi kokulu nesneler yapmak.'),
(49592, 'T0', 'TAGLİF-İ SÜYUF', 'taglif-i süyuf', ' Kılıçları kılıfa koyma. * Mc: Sulh yapma, barışma.'),
(49593, 'T0', 'TAGLİK', 'taglik', ' (C.: Taglikat) (Galak. dan) Kapama, kapanılma. * Kilitleme. * Edb: Muğlak ve kapalı söz söyleme.'),
(49594, 'T0', 'TAGLİS', 'taglis', ' Fık: Kurban bayramının ilk gününde Müzdelife''de bulunanlar için o günün Sabah Namazını fecri müteakib daha ortalık karanlık iken kılmak. (Bu çok efdaldir) * Bir işi üzerine almak. * Sabah karanlığında sefer etmek.'),
(49595, 'T0', 'TAGLİT', 'taglit', ' (Galat. dan) Yanlışını çıkarma. Yanıltma. * Karıştırma.'),
(49596, 'T0', 'TAGLİYE', 'tagliye', ' Pahalanma. * Kaynatma.'),
(49597, 'T0', 'TAGLİZ', 'tagliz', ' (Gılzet. den) Kabalaştırma. Kaba ve galiz yapma. * Kaba söyleme. * Pahalanma.'),
(49598, 'T0', 'TAGMİD', 'tagmid', ' Kınına koyma.'),
(49599, 'T0', 'TAGMİS', 'tagmis', ' Batırma, daldırma.'),
(49600, 'T0', 'TAGMİYE', 'tagmiye', ' Evin üstüne direk yapmak. * Yüzü bir şeyle örtmek.'),
(49601, 'T0', 'TAGMİZ', 'tagmiz', ' Sıkmak. * Gövdesini sıktırıp ovdurmak.'),
(49602, 'T0', 'TAGMİZ', 'tagmiz', ' Göz yummak. * Sözü müşkil söylemek.'),
(49603, 'T0', 'TAGNİYE', 'tagniye', ' (Gınâ. dan) Birini zengin etmek.'),
(49604, 'T0', 'TAGR', 'tagr', ' (C.: Tagrân) Bir küçük kuş.'),
(49605, 'T0', 'TAGRİB', 'tagrib', ' (Gurbet. den) Birini gurbete gönderme. * Memleketten çıkarma, uzaklaştırılma. * Kovma.'),
(49606, 'T0', 'TAGRİD', 'tagrid', ' Çağırmak. * Kuş ötmek.'),
(49607, 'T0', 'TAGRİK', 'tagrik', ' (Gark. dan) Suda boğma.'),
(49608, 'T0', 'TAGRİM', 'tagrim', ' Ödetme. Ödenme.'),
(49609, 'T0', 'TAGRİM-İ DÜYUN', 'tagrim-i düyun', ' Borçların ödenmesi.'),
(49610, 'T0', 'TAGRİR', 'tagrir', ' (C.: Tagrirât) (Gurur. dan) Müşteriyi aldatma. Gurur verip aldatma. * Tehlikeli yerlere düşürmek.'),
(49611, 'T0', 'TAGRİS', 'tagris', ' (Gars. dan) Yere dikme.'),
(49612, 'T0', 'TAGRİS', 'tagris', ' Aç etmek.'),
(49613, 'T0', 'TAGRİZ', 'tagriz', ' Batırmak. * Çekirgenin kuyruğunu yere batırması.'),
(49614, 'T0', 'TAGŞİŞ', 'tagşiş', ' (Gışş. dan) Karıştırmak saflığını gidermek. Değerli bir şeyi değeri olmayan şeylerle karıştırmak. * Aklı gidermek. * Hayran etmek.'),
(49615, 'T0', 'TAGŞİYE', 'tagşiye', ' (Gışâ. dan) Örtmek, örtünmek. Bürünmek. * (Gaşi. den) Kendinden geçirilmek.'),
(49616, 'T0', 'TAGTİYE', 'tagtiye', ' Örtme, örtülme.'),
(49617, 'T0', 'TAGUN', 'tagun', ' Azgın kimseler. * Cenab-ı Hakk''ın emir ve kanunlarından gaflet edip haksızlık edenler, zulüm edenler.'),
(49618, 'T0', 'TAGUT', 'tagut', ' İnsanları Allah''a (C.C.) karşı isyana sevkeden. İsyankâr. * Her bâtıl mâbud. * Şeytan. * İslâmiyetten önce Kâbe''deki putlardan birinin ismi.'),
(49619, 'T0', 'TAGVA', 'tagva', ' Tuğyan. Azgınlık.'),
(49620, 'T0', 'TAGVİR', 'tagvir', ' Sonuna yetişmek. * Çukur yapmak. * Öğle vaktinde uyumak.'),
(49621, 'T0', 'TAGVİS', 'tagvis', ' Medet istemek, yardım istemek.'),
(49622, 'T0', 'TAGVİYE', 'tagviye', ' Azdırıp yoldan saptırma, baştan çıkarma.'),
(49623, 'T0', 'TAGYİB', 'tagyib', ' Kaybetmek.'),
(49624, 'T0', 'TAGYİM', 'tagyim', ' (Hava) bulutlu olmak.'),
(49625, 'T0', 'TAGYİR', 'tagyir', ' Başkalaştırma. Değiştirme. Bozma. * İyiden kötüye değiştirme.'),
(49626, 'T0', 'TAGYİRÂT', 'tagyirat', ' (Tagyir. C.) Değiştirmeler, başkalaştırmalar; bozmalar.'),
(49627, 'T0', 'TAGYİZ', 'tagyiz', ' (Gayz. dan) Hiddetlendirme, kızdırma, öfkelendirme.'),
(49628, 'T0', 'TAGZİN', 'tagzin', ' Hışım etmek, kızmak. * Buruşturmak.'),
(49629, 'T0', 'TAGZİT', 'tagzit', ' Çok sıkı bağlama. Tazyik etme, basınç yapma.'),
(49630, 'T0', 'TAGZİYE', 'tagziye', ' Gazâ ettirme, din uğrunda savaştırma.'),
(49631, 'T0', 'TAGZİZ', 'tagziz', ' Gümüşle süslemek.'),
(49632, 'T0', 'TAH', 'tah', ' Hamur.'),
(49633, 'T0', 'TAH', 'tah', ' Atmak. * Uzaklaştırmak, ırak etmek. * Cimâ etmek.'),
