(50769, 'T0', 'TATURE', 'tature', ' f. Hayvanların ayağına vurulan köstek, bukağı.'),
(50770, 'T0', 'TATVİ''', 'tatvi''', ' Muti etmek, itaat ettirmek, boyun eğdirmek.'),
(50771, 'T0', 'TATVİF', 'tatvif', ' Tavaf ettirmek.'),
(50772, 'T0', 'TATVİK', 'tatvik', ' Boynuna gerdanlık takınmak.'),
(50773, 'T0', 'TATVİL', 'tatvil', ' Uzatma. Uzatılma.'),
(50774, 'T0', 'TATVİL-İ KELÂM', 'tatvil-i kelam', ' Uzun konuşma. Sözü uzatma.'),
(50775, 'T0', 'TATVİLÂT', 'tatvilat', ' (Tatvil. C.) Boş, beyhude ve fazla sözler.'),
(50776, 'T0', 'TATVİŞ', 'tatviş', ' Burma, iğdiş etme.'),
(50777, 'T0', 'TATYİB', 'tatyib', ' İyi davranma. İyi muâmele etme. Hoş etme. Gönlünü hoş etme.'),
