INSERT INTO `db_lugat` (`id`, `indeks`, `kelime`, `kirpilmis`, `anlam`) VALUES
(54946, 'U1', 'ÜHCİYYE', 'ühciyye', ' (Ühcüvve) Hicvetmeğe sebep olan şey.'),
(54947, 'U1', 'ÜHCÜVVE', 'ühcüvve', ' Hicvetmeğe sebep olan şey. * Yerme, hicvetme.'),
(54948, 'U1', 'ÜHKUME', 'ühkume', ' Alaylı söz veya hal.'),
(54949, 'U1', 'ÜKEL', 'ükel', ' (Ükle. C.) Lokmalar.'),
(54950, 'U1', 'ÜKİLE', 'ükile', ' Gıybet.'),
(54951, 'U1', 'ÜKL', 'ükl', ' (Ükül) Meyve, yiyecek, azık. * Zekâ.'),
(54952, 'U1', 'ÜKLE', 'ükle', ' (C.: Ükel) Lokma.'),
(54953, 'U1', 'ÜKNE', 'ükne', ' Çukur içinde olan kuş yuvası.'),
(54954, 'U1', 'ÜKRE', 'ükre', ' Yuvarlak nesne. Top. * Çukur.'),
(54955, 'U1', 'ÜKRUME', 'ükrume', ' Kerem, bahşiş, lütuf.'),
(54956, 'U1', 'ÜKSUM', 'üksum', ' Çimenlik yer. Çayırı bol ve güzel olan bahçe.'),
(54957, 'U1', 'ÜKSUS', 'üksus', ' Sarmaşık.'),
(54958, 'U1', 'ÜKULE', 'ükule', ' Sürüden ayırıp beslenilen koyun.'),
(54959, 'U1', 'ÜKÜL', 'ükül', ' (Bak: Ükl)'),
(54960, 'U1', 'ÜKZUBE', 'ükzube', ' Yalan. Uydurma, söz.'),
(54961, 'U1', 'ÜLBE', 'ülbe', ' Kıtlık. * Açlık.'),
(54962, 'U1', 'ÜLBUB', 'ülbub', ' Kiraz çekirdeği.'),
(54963, 'U1', 'ÜLEMA', 'ülema', ' (Bak: Ulemâ)'),
(54964, 'U1', 'ÜLFET', 'ülfet', ' Alışma, alışkanlık. Birisiyle münasebette bulunmak. Ünsiyet. Ahbablık, dostluk. Huy etme. Görüşme, konuşma.(İnsanları fikren dalâlete atan sebeblerden biri; ülfeti, ilim telâkki etmeleridir. Yâni me''lufları olan şeyleri kendilerince mâlum bilirler. Hattâ ülfet dolayısıyla âdiyata teemmül edip ehemmiyet vermezler. Halbuki ülfetlerinden dolayı mâlum zannettikleri o âdi şeyler birer hârika ve birer mu''cize-i kudret oldukları halde, ülfet sâikasiyle onları teemmüle, dikkate almıyorlar; ta onların fevkinde olan tecelliyat-ı seyyâleye im''an-ı nazar edebilsinler. Bunların meseli deniz kenarında durup, denizin içerisindeki hayvanata ve sâir garip halâtına bakmıyarak yalnız rüzgâr ile husule gelen dalgalara ve şemsin şuâatından peyda olan parıltısına dikkat etmekle Mâlik-ül Bihâr olan Allah''ın azametine delil getiren adamın meseli gibidir.İ''lem Eyyühel-Aziz! İnsanların arza âit mâlumat ve müsellemat-ı bedihiyatları ülfete mebnidir. Ülfet ise, cehl-i mürekkeb üstüne serilmiş bir perdedir. Hakikate bakılırsa zannettikleri ilim, cehildir. Bu sırra binaendir ki, Kur''an, âyetleriyle insanların nazarını me''lufatları olan şeylere çeviriyor. Âyetler, necimler gibi ülfet perdesini deler atar. İnsanın kulağından tutar, başını eğdirir. O ülfetin altındaki havârik-ul-âdât mu''cizeleri o âdiyat içerisinde gösterir. M.N.) (Bak: Tefekkür)'),
(54965, 'U1', 'ÜLFETGER', 'ülfetger', ' f. Ülfet eden. Ülfet edici.'),
(54966, 'U1', 'ÜLHİYYE', 'ülhiyye', ' Çocuk oyuncağı, oyuncak.'),
(54967, 'U1', 'ÜLHÜVVE', 'ülhüvve', ' Oyuncak, çocuk oyuncağı.'),
(54968, 'U1', 'ÜLİNNÜHA', 'ülinnüha', ' (Üli-n nühâ) Akıllı kimseler.'),
(54969, 'U1', 'ÜLKER', 'ülker', ' (Bak: Süreyya)'),
(54970, 'U1', 'ÜLKÜ', 'ülkü', ' Bazı öz türkçecilik taraftarlarınca kullanılmış bir kelimedir. Divan-ı Lügat-ıt Türk''te "Peyman" mânasına geldiğine merhum A. Hamdi Elmalılı işaret ediyor: "Ahd ü misak" da denir. Emanî, ideal mânâsına kullananlar varsa da yanlıştır.'),
(54971, 'U1', 'ÜLTİMATOM', 'ültimatom', ' (Oltimatom) Fr. Kat''i ve dönülmez söz. Son söz. * Bir devletin başka bir devlete verdiği ihtar.'),
(54972, 'U1', 'ÜL''UBE', 'ül''ube', ' Piyes, oyun.'),
(54973, 'U1', 'ÜLUF', 'üluf', ' Binler. (Bak: Uluf)'),
(54974, 'U1', 'ÜLUHİYET', 'üluhiyet', ' (Bak: Uluhiyet)'),
(54975, 'U1', 'ÜL''ÜBAN', 'ül''üban', ' Oyuncu, aktör.'),
(54976, 'U1', 'ÜLÜM', 'ülüm', ' f. Bölük, takım, cemaat.'),
(54977, 'U1', 'ÜLYA', 'ülya', ' (Bak: Ulyâ)'),
(54978, 'U1', 'ÜMA''', 'üma''', ' Kedi miyavlaması.'),
(54979, 'U1', 'ÜMDUD', 'ümdud', ' Usûl, âdet, görenek.'),
(54980, 'U1', 'ÜMDUHA', 'ümduha', ' Medhedilmeğe sebep olan hal veya iş.'),
(54981, 'U1', 'ÜMEM', 'ümem', ' (Ümmet. C.) Ümmetler. Milletler.'),
(54982, 'U1', 'ÜMEM-İ SÂLİFE', 'ümem-i salife', ' Geçmişteki ümmetler. İslâmiyetten evvel diğer Peygamberlere tâbi olmuş ümmetler.'),
(54983, 'U1', 'ÜMENA', 'ümena', ' Emin kimseler. Eminler. Emniyet sahibleri.'),
(54984, 'U1', 'ÜMERA', 'ümera', ' (Emir. C.) Emirler, beyler. Seyyidler. şerifler. * Yüksek rütbeli zabitler.'),
(54985, 'U1', 'ÜMHUD', 'ümhud', ' Çömlek. * Tuzluk.'),
(54986, 'U1', 'ÜMİD', 'ümid', ' f. Ummak. Emel. Arzu. İntizar. Umut. Rica.'),
(54987, 'U1', 'ÜMİDBAHŞ', 'ümidbahş', ' f. Ümitlendiren, ümit veren.'),
(54988, 'U1', 'ÜMİDBESTE', 'ümidbeste', ' f. Ümitlenmiş, ümit bağlamış.'),
(54989, 'U1', 'ÜMİDGÂH', 'ümidgah', ' f. Bir şey ümit edilen yer veya makam.'),
(54990, 'U1', 'ÜMİDVÂR', 'ümidvar', ' f. Ümitli. Ümit besleyen.(Evet, ümidvâr olunuz; şu istikbal inkılâbı içinde en yüksek gür sadâ, İslâmın sadâsı olacaktır. M.) (Rahmet-i İlâhiyyeden ümid kesilmez. Çünkü Cenab-ı Hak bin seneden beri Kur''anın hizmetinde istihdam ettiği ve ona bayraktar tayin ettiği bu vatandaşların muhteşem ordusunu ve muazzam cemaatını muvakkat arızalarla inşâallah perişan etmez. Yine o nuru ışıklandırır ve vazifesini idame ettirir... M.)'),
(54991, 'U1', 'ÜMLUC', 'ümluc', ' Yaprak. * Selvi yaprağına benzer uzun, karışık bir ot.'),
(54992, 'U1', 'ÜMLUD', 'ümlud', ' (C: Müled) Kamış dalı.'),
(54993, 'U1', 'ÜMM', 'ümm', ' Ana, anne, vâlide. Nine. * Asıl, esas. * Başlıca olan şey.'),
(54994, 'U1', 'ÜMM-İ SELEME', 'ümm-i seleme', ' (Mi: 542-626) Ümmehât-ı Mü''minînden olup, Resül-ü Ekrem Aleyhissalâtü Vesselâm''ın son vefat eden zevcesi idi. 378 Hadis-i şerif rivayet etti. (R.A.)'),
(54995, 'U1', 'ÜMM-ÜD DEM', 'ümm-üd dem', ' Kırmızı kan damarlarında görülen kabarma. Bu nabız damarlarından birisine açılan kan kesesi.'),
(54996, 'U1', 'ÜMM-ÜD DİMAĞ', 'ümm-üd dimağ', ' Beyin zarı.'),
(54997, 'U1', 'ÜMM-ÜD DÜNYA', 'ümm-üd dünya', ' Dünyanın anası. Mısır.'),
(54998, 'U1', 'ÜMM-ÜL BİLÂD', 'ümm-ül bilad', ' Mekke-i Mükerreme.'),
(54999, 'U1', 'ÜMM-ÜL HABÂİS', 'ümm-ül habais', ' Şarap, rakı gibi haram olan içki.'),
(55000, 'U1', 'ÜMM-ÜL KİTAB', 'ümm-ül kitab', ' Kitabın anası, esası. Levh-i Mahfuz ve ilm-i İlâhî. (Yâni: Kur''ân, İlm-i İlâhîde, Levh-i Mahfuz''da ezelî ve ebedî olarak mahfuz bulunduğundan Kur''anın aslı ve anası mânasında kullanılan bir tabirdir.) * Kur''an-ı Kerim''in müteşabih olmayan muhkem âyetlerine de kitabın anası, esası mânasında Ümm-ül Kitab denilir. * Fâtiha Suresi. * Diğer bir mânada bütün müsbet ve faydalı kitabların anası ve mercii olarak Kur''an-ı Kerim''e de denir.)'),
(55001, 'U1', 'ÜMM-ÜL KURÂ', 'ümm-ül kura', ' Mekke-i Mükerreme.'),
(55002, 'U1', 'ÜMM-ÜL KUR''AN', 'ümm-ül kur''an', ' Fâtiha Suresi.'),
(55003, 'U1', 'ÜMM-ÜL VELED', 'ümm-ül veled', ' Huk: Çocuğunun kendi efendisinden olduğunu söyleyen çocuk doğurmuş cariye.'),
(55004, 'U1', 'ÜMM-ÜN NÂFİ''', 'ümm-ün nafi''', ' Tavuk.'),
(55005, 'U1', 'ÜMM-ÜN NÜCUM', 'ümm-ün nücum', ' Gök. Sema.'),
(55006, 'U1', 'ÜMM-ÜT TAÂM', 'ümm-üt taam', ' Buğday.'),
(55007, 'U1', 'ÜMM-ÜT TÂRIK', 'ümm-üt tarık', ' Deve kuşu.'),
(55008, 'U1', 'ÜMM-ÜT TARÎK', 'ümm-üt tarik', ' Ulu yol. Yüce yol.'),
(55009, 'U1', 'ÜMMAN', 'ümman', ' Emin kimse. Emniyetli kişi.'),
(55010, 'U1', 'ÜMMEHAT', 'ümmehat', ' (Ümm. C.) Analar. * Esaslar, asıllar. * İslâmî ana eserler. Me''haz olabilecek kıymetli ilmî eserler.'),
(55011, 'U1', 'ÜMMEHÂT-ÜL MÜ''MİNÎN', 'ümmehat-ül mü''minin', ' Mü''minlerin anaları. Peygamberimiz Resül-ü Ekrem Aleyhissalâtü Vesselâm''ın mübarek zevceleri.'),
(55012, 'U1', 'ÜMMET', 'ümmet', ' Cemaat, kavim, taife. * Bir hâkim milletin ashabından olan hey''et-i içtimaiye. * Bir peygambere inanıp onun yolundan giden insanların hepsi. Bir peygamberin Hakka davet ettiği cemaat. * Bir dille konuşan millet. * Arkasına düşülecek bir cemaat veya tarikat.'),
(55013, 'U1', 'ÜMMET-İ KAİME', 'ümmet-i kaime', ' Hakşinas, doğru, doğrudan ve Allah için kalkan, müstakim ve âdil ümmet.'),
(55014, 'U1', 'ÜMMİ', 'ümmi', ' Anasından doğduğu gibi kalmış ve tahsil görmemiş, mekteb ve medresede okumamış kimse. Yazı yazmak bilmeyen. (Ümmi ile câhil arasında fark vardır. Ümmi yalnız okuyup yazmak bilmiyendir. Câhil ise, okuyup yazmak bilse de, bir şey bilmiyen kimsedir, her ümmi câhil değildir.) * Anaya mensub olan.(Mefhar-i Âlem (A.S.M.) hiç bir mektebde, medresede ve hiçbir beşerden tahsil görmeden, ümmiliğiyle beraber, evvel, âhir ilimlerle mücehhez olması, Âlem-i İslâma, âlemlere ve dünyaya rahmet olması ve Onun bir misli ve benzeri bulunmaması, en büyük mu''cizelerden ve Hak Peygamber olduğuna dair en mühim delillerdendir.)'),
(55015, 'U1', 'ÜMMİ SİNAN', 'ümmi sinan', ' (Vefatı Hi: 958, Mi: 1551) Halvetî Tarikatı, Sinaniye kolunun piridir. Bursa''lı olduğu nakledilir. Karaman''lı olduğu hakkında da rivayet vardır. Risale-i Şerife-i İstanbulî Ümmi Sinan adında bir eseri vardır. (R. Aleyh.) (Osmanlı Müellifleri sh: 214)'),
(55016, 'U1', 'ÜMMİYANE', 'ümmiyane', ' f. Bir şey bilmiyormuşçasına. Ümmilere yakışır halde. Okur yazar olmadan.'),
(55017, 'U1', 'ÜMMİYYE', 'ümmiyye', ' Analık, annelik.'),
(55018, 'U1', 'ÜMMİYET', 'ümmiyet', ' Ümmi oluş. Ümmi kimsenin hali. Okur-yazarlığı olmamak.'),
(55019, 'U1', 'ÜMNİYYE', 'ümniyye', ' Umut, ümid. * Arzu, istek, talep. * Niyet, kuruntu.'),
(55020, 'U1', 'ÜMSÜLE', 'ümsüle', ' Örnek olarak verilen beyit. Misal olarak gösterilen mısra.'),
(55021, 'U1', 'ÜMUMET', 'ümumet', ' (Ümm. den) Annelik, analık.'),
(55022, 'U1', 'ÜM''UZ', 'üm''uz', ' Keçi veya karaca.'),
(55023, 'U1', 'ÜMÜLDAN', 'ümüldan', ' Taze fidan. Körpe dal. * Genç, güzel. * İnce ve narin vücud.'),
(55024, 'U1', 'ÜNAFİ', 'ünafi', ' Büyük burunlu kimse.'),
(55025, 'U1', 'ÜNAH', 'ünah', ' Süstlük, zayıflık.'),
(55026, 'U1', 'ÜNAN', 'ünan', ' İnleme.'),
(55027, 'U1', 'ÜNAS', 'ünas', ' Halk. İnsanlar.'),
(55028, 'U1', 'ÜNBUB', 'ünbub', ' (Ünbube) Kamıştaki boğum arası kısım. * Parmak uçları. * Tüp. İnce boru.'),
(55029, 'U1', 'ÜNBUSE', 'ünbuse', ' Çocukların oyunu.'),
(55030, 'U1', 'ÜNBUŞ', 'ünbuş', ' (Ünbûşe) Bitki kökü. Kökü yerden takımıyla birlikte çıkarılan fidan.'),
(55031, 'U1', 'ÜNCUC', 'üncuc', ' (C.: Anâcic) Hızlı yürüyen at.'),
(55032, 'U1', 'ÜNCUR', 'üncur', ' Şişe kılıfı.'),
(55033, 'U1', 'ÜNF', 'ünf', ' (Bak: Unf)'),
(55034, 'U1', 'ÜNKUA', 'ünkua', ' Yağ biriken yer.'),
(55035, 'U1', 'ÜNMA', 'ünma', ' İçi saman veya ot doldurulmuş şey.'),
(55036, 'U1', 'ÜNS', 'üns', ' Alışkanlık, alışma. * Arkadaş. Hemdem.'),
(55037, 'U1', 'ÜNS TUTMAK', 'üns tutmak', ' Alışmak, birlikte düşüp kalkmak.'),
(55038, 'U1', 'ÜNSA', 'ünsa', ' Dişi. Kadın, kız.'),
(55039, 'U1', 'ÜNSA-ÜNS', 'ünsa-üns', ' Sıkıfıkı konuşma.'),
(55040, 'U1', 'ÜNSÎ', 'ünsi', ' (Ünsiye) Alışmış, ünsiyet etmiş, sokulgan. * Arkadaş.'),
(55041, 'U1', 'ÜNSİYET', 'ünsiyet', ' Alışkanlık, dostluk. Birlikte düşüp kalkmak. Ahbablık.'),
(55042, 'U1', 'ÜNŞUDE', 'ünşude', ' (Bak: Neşide)'),
(55043, 'U1', 'ÜNŞUTA', 'ünşuta', ' Düğüm, ilmik.'),
(55044, 'U1', 'ÜNUF', 'ünuf', ' Henüz daha yedirilmemiş olan çayır. * (Enf. C.) Burunlar.'),
(55045, 'U1', 'ÜNUSET', 'ünuset', ' Dişilik. Müennes oluş.'),
(55046, 'U1', 'ÜNÜN', 'ünün', ' Ayağı ve burnu kırmızı, vücudu kara olan bir kuş.'),
(55047, 'U1', 'ÜNVAN', 'ünvan', ' İsim. Lâkab. Adres. * Önsöz, mukaddeme.'),
(55048, 'U1', 'ÜNVAN-I MÜLÂHAZA', 'ünvan-ı mülahaza', ' Bir şeyin hakikatını bir derece düşünebilmek için olan isim, tabir ve vasıta.(Mi''raciyedeki mâceralar, mâlumumuz olan mânalarla, o kudsi ve nezih hakikatları ifade edemiyor. Belki o muhavereler birer ünvan-ı mülâhazadır; birer mirsad-ı tefekkürdür ve ulvi ve derin hakaika birer işarettir ve imanın bir kısım hakaikına birer ihtardır. Ve kabil-i tabir olmayan bazı mânalara birer kinayedir. Yoksa ma''lumumuz olan mânalar ile birer mâcera değil. Biz hayalimiz ile o muhaverelerden o hakikatları alamayız; belki kalbimizle heyecanlı bir zevk-i imanî ve nuranî bir neş''e-i ruhanî alabiliriz. M.)'),
(55049, 'U1', 'ÜNZUHA', 'ünzuha', ' Gurur, kibir, büyüklük.'),
(55050, 'U1', 'ÜRBA', 'ürba', ' Belâ, mihnet.'),
(55051, 'U1', 'ÜRBE', 'ürbe', ' Büklüm. * Düğüm. * Hile.'),
(55052, 'U1', 'ÜRBUN', 'ürbun', ' Pey akçesi, pey olarak verilen para.'),
(55053, 'U1', 'ÜRCUCE', 'ürcuce', ' Salıncak.'),
(55054, 'U1', 'ÜRCUFE', 'ürcufe', ' (C.: Erâcif) Yalan. Uydurma söz.'),
(55055, 'U1', 'ÜRCUHA', 'ürcuha', ' Salıncak.'),
(55056, 'U1', 'ÜRCUZE', 'ürcuze', ' (Recez. den) Edb: Mısraları kafiyeli, kısa vezinli nazım. (Bak: Kaside)'),
(55057, 'U1', 'ÜRD', 'ürd', ' f. Gibi, benzer.'),
(55058, 'U1', 'ÜRDÜNN', 'ürdünn', ' Uyuklamak. * Bir büyük ırmak.'),
(55059, 'U1', 'ÜRK', 'ürk', ' Mekân, mevki.'),
(55060, 'U1', 'ÜRMULE', 'ürmule', ' (C.: Erâmil) Ergen delikanlı.'),
(55061, 'U1', 'ÜRNE', 'ürne', ' Taze peynir. * Keler tuzağı olan yer.'),
(55062, 'U1', 'ÜRÜMEK', 'ürümek', ' f. Havlamak. (İt ürür, kervan yürür)Ürüyen köpek ısırmaz: Tehdit savuran, işi gürültüye boğan kimselerden yılmamak lâzım geldiğini anlatır.'),
(55063, 'U1', 'ÜRVİYYE', 'ürviyye', ' (C.: Ervâ-Erâvi) Dağ keçisinin dişisi.'),
(55064, 'U1', 'ÜRYAN', 'üryan', ' (Bak: Uryan)'),
(55065, 'U1', 'ÜSAL', 'üsal', ' Çok miktar mal.'),
(55066, 'U1', 'ÜSAME', 'üsame', ' Davar otlatmak. * Arslan.'),
(55067, 'U1', 'ÜSAME BİN ZEYD (R.A.)', 'üsame bin zeyd (r.a.)', ' Resül-ü Ekrem Aleyhissalâtü Vesselâm''ın azadlısı olan Zeyd bin Harise''nin oğludur. Meşhur sahabedendir. 128 Hadis-i Şerif rivayet etmiştir. 75 yaşında iken 54 yılında vefat etmiştir. (R.A.)'),
(55068, 'U1', 'ÜSARA', 'üsara', ' (Bak: Üsera)'),
(55069, 'U1', 'ÜSARE', 'üsare', ' (Bak: Usare)'),
(55070, 'U1', 'ÜSBU''', 'üsbu''', ' Hafta. Yedi günlük zaman.'),
(55071, 'U1', 'ÜSBUBE', 'üsbube', ' (C.: Esâbib) Sövme, küfür.'),
(55072, 'U1', 'ÜSBUÎ', 'üsbui', ' (Üsbuiyye) Haftalık.'),
(55073, 'U1', 'ÜSERA', 'üsera', ' (Üsârâ) Esirler. Harbde teslim alınanlar. * Köleler.'),
(55074, 'U1', 'ÜSFİYYE', 'üsfiyye', ' (C.: Esâfi) Üzerine tencere koyup yemek pişirilen ocak taşı.'),
(55075, 'U1', 'ÜSİR', 'üsir', ' Yaranın iyi olduktan sonra kalan izi.'),
(55076, 'U1', 'ÜSKUB', 'üskub', ' Sıra ile dikilmiş olan ağaçlar. * Kunduracı. * Dökülmüş olan, akan su. * Demirci.'),
(55077, 'U1', 'ÜSKUF', 'üskuf', ' (C.: Esâkıf) Kâfirlerin kadısı ve ruhbanları.'),
(55078, 'U1', 'ÜSKUF', 'üskuf', ' (C.: Esâkife) Pabuç diken, kunduracı.'),
(55079, 'U1', 'ÜSKUTUSS', 'üskutuss', ' (Rumcadan) Cevher, asıl, unsur, madde.'),
(55080, 'U1', 'ÜSKUN', 'üskun', ' Koruk halinde hurma salkımı.'),
(55081, 'U1', 'ÜSKÜDAR', 'üsküdar', ' Mushaf cildi.'),
(55082, 'U1', 'ÜSKÜFFE', 'üsküffe', ' Eşik tahtası.'),
(55083, 'U1', 'ÜSKÜR', 'üskür', ' f. Kirpi.'),
(55084, 'U1', 'ÜSLEM', 'üslem', ' El arkasında hınsırla pınsır arasındaki damar.'),
(55085, 'U1', 'ÜSLUB', 'üslub', ' Tarz, yol. Biçim. İfade tarzı. Dizmek.'),
(55086, 'U1', 'ÜSLUB-U ÂDÎ', 'üslub-u adi', ' Alelâde ifade tarzı. İfadesinde hiçbir üstünlük bulunmayan tarz.'),
(55087, 'U1', 'ÜSLUB-U ÂLÎ', 'üslub-u ali', ' Edb: Üstün ifade tarzı. İfadenin yüksek ve nezih olanı.'),
(55088, 'U1', 'ÜSLUB-U HAKÎM', 'üslub-u hakim', ' Edebî san''atlardan biridir. Sorulan bir suale, soranın halini nazara alarak başka bir sual gibi telâkki edip, ona göre cevab vermek demektir. Meselâ : Bazı Ashab Resulüllah''a (A.S.M.) hilâlin ince başlayıp, kalınlaşarak bedr şekline gelip, sonra yine başladığı şekle dönmesinin sebebini sordular. Bunun cevabı onlara lâzım olmadığı için, Kur''ân-ı Kerim o vaziyetin neticesine terettüb eden hikmeti, yani ayın takvimcilik yaptığını söylemiştir. Çünkü bu, soranlar için daha mühim ve anlaşılması daha kolaydır.'),
(55089, 'U1', 'ÜSLUB-U MÜCERRED', 'üslub-u mücerred', ' (Sade üslub) Bu üslupta tabiîlik, akıcılık, selâset, kısalık, mânâ ve maksada kifayet sıfatları vardır. Bu üslup, âlet ilimlerinde, ders kitablarında, konuşmalarda ve beşerî muamelelerde kullanılır.'),
(55090, 'U1', 'ÜSLUB-U MÜZEYYEN', 'üslub-u müzeyyen', ' (Ziynetli ve parlak üslub) Bu üslub tergib ve terhib (teşvik etme ve sakındırma) gibi hususları tazammun eder. Hitabiyat ve iknaiyatta kullanılır.'),
(55091, 'U1', 'ÜSLUB-PERESTLİK', 'üslub-perestlik', ' Kelâmın mâna ve maksada uygunluğuna değil de, ifade tarzının güzelliğine önem vermek.'),
(55092, 'U1', 'ÜSR', 'üsr', ' Sidik tutulması, sidik zoru.'),
(55093, 'U1', 'ÜSRE', 'üsre', ' Seleften gelen şan şeref. * Söz veya hadis nakletmek.'),
(55094, 'U1', 'ÜSRE', 'üsre', ' Cemaat, topluluk.'),
(55095, 'U1', 'ÜSRUŞ', 'üsruş', ' f. Güzel ses.'),
(55096, 'U1', 'ÜSRÜB', 'üsrüb', ' f. Kurşun.'),
(55097, 'U1', 'ÜSS', 'üss', ' Esas, asıl. Kök, temel. * Askerlikte herhangi bir düşman hücumuna karşı esas dayanak olmak üzere önceden hazırlanmış yer. * Harb gemilerinin, noksanlıklarını tamamladıkları yer. * Mat: Bir sayının hangi kuvvete çıkarıldığını gösteren sayı.'),
(55098, 'U1', 'ÜSS-ÜL ESAS', 'üss-ül esas', ' Hakiki sağlam temel.'),
(55099, 'U1', 'ÜSS-ÜL HAREKÂT', 'üss-ül harekat', ' Askerî harekâtın başlangıcına esas olan yer.'),
(55100, 'U1', 'ÜSTAD', 'üstad', ' (Üstaz) İlim veya san''atta üstün olan kimse. Usta, san''atkâr. Muallim, profesör. Bilgide veya san''atta veya amelde meharetli zât.'),
(55101, 'U1', 'ÜSTAD-I A''ZAM', 'üstad-ı a''zam', ' En büyük üstad. Muallimlerin en üstünü ve reisi olan.'),
(55102, 'U1', 'ÜSTAD-I EZELÎ', 'üstad-ı ezeli', ' Cenab-ı Hak. Bütün ilim ve bilgilerin, marifetlerin öğreticisi. Alîm-i Mutlak ve Hakîm-i Ezelî.(... Hem maden-i kemalât ve muallim-i ahlâk-ı âliye olan o dellâl-ı vahdaniyet ve saadet kendi kendine söylemiyor, belki söylettiriliyor. Üstad-ı Ezelîsinden ders alır, sonra ders verir... M.)'),
(55103, 'U1', 'ÜSTAD-I KÜLL', 'üstad-ı küll', ' Herkesin üstadı. Her çeşit ilimde çok ileri bilgisi olan.'),
(55104, 'U1', 'ÜSTAD-ÜL BEŞER', 'üstad-ül beşer', ' Beşerin bütün insanlığın üstadı, hocası, daha bilgili ve ârif. Muhammed Aleyhissalâtü Vesselam.'),
(55105, 'U1', 'ÜSTADANE', 'üstadane', ' f. Üstâda yakışır surette. Ustaca.'),
(55106, 'U1', 'ÜSTADÎ', 'üstadi', ' f. Üstadlık, ustalık.'),
(55107, 'U1', 'ÜSTAH', 'üstah', ' f. Edebsiz, hayasız, utanmaz kimse.'),
(55108, 'U1', 'ÜSTAM', 'üstam', ' f. Güvenilir, itimad edilir, inanılır, emin. * Gümüş veya altından yapılmış üzengi, at eyeri.'),
(55109, 'U1', 'ÜSTİBAH', 'üstibah', ' Masura.'),
(55110, 'U1', 'ÜST PERDEDEN BAŞLAMAK', 'üst perdeden başlamak', ' Ağız bozmak, sert konuşmak.'),
(55111, 'U1', 'ÜSTUN', 'üstun', ' f. Direk. Sütun.'),
(55112, 'U1', 'ÜSTUR', 'üstur', ' f. At, katır davar gibi dört ayaklı hayvan. '),
(55113, 'U1', 'ÜSTURE', 'üsture', ' Edb: Efsane, uydurma hikâye demek olan "esâtir" kelimesinin müfredidir.'),
(55114, 'U1', 'ÜSTÜHAN', 'üstühan', ' f. Kemik.'),
(55115, 'U1', 'ÜSTÜHANPÂRE', 'üstühanpare', ' Kemik parçası.'),
(55116, 'U1', 'ÜSTÜKUS', 'üstükus', ' (C.: Üstükusât) Cevher, madde, asıl. * Geometri.'),
(55117, 'U1', 'ÜSTÜMM', 'üstümm', ' (C.: Esâtim) Deniz suyunun toplandığı yer.'),
(55118, 'U1', 'ÜSTÜMME', 'üstümme', ' Orta, vasat.'),
(55119, 'U1', 'ÜSTÜRE', 'üstüre', ' f. Ustura.'),
(55120, 'U1', 'ÜSTÜVANE', 'üstüvane', ' Geo: Silindir. Direk şeklindeki sütun. İçi boş direk şekli.'),
(55121, 'U1', 'ÜSTÜVAR', 'üstüvar', ' f. Kuvvetli, dayanıklı, sağlam, muhkem. * Güvenilir, itimad edilir.'),
(55122, 'U1', 'ÜSTÜVARİ', 'üstüvari', ' f. Sağlam, kuvvetli, emniyetli.'),
(55123, 'U1', 'ÜSUN', 'üsun', ' Suyun tad ve renginin değişmesi. * Bir kimse kuyuya girdiğinde buharından veya murdar kokulardan dolayı aklının gitmesi.'),
(55124, 'U1', 'ÜSÜR', 'üsür', ' Yara izi. * Kılıcın rengi ve cevheri.'),
(55125, 'U1', 'ÜSVE(T)', 'üsve(t)', ' Beraberlik. * Halka reis olmak. * Dert ortağı. Sâdık arkadaş. Manevî tabib. * Nümune ve örnek tutulacak olan insan.'),
(55126, 'U1', 'ÜŞABE', 'üşabe', ' Irkı, nesebi karışık adam. * Karışık cemaat. * Rüşvet ve hırsızlık gibi yollarla elde edilen kazanç.'),
(55127, 'U1', 'ÜŞBE', 'üşbe', ' Kurt, böcek.'),
(55128, 'U1', 'ÜŞER', 'üşer', ' Dişlerini birbirine sürüp keskinleştirmek.'),
(55129, 'U1', 'ÜŞGULE', 'üşgule', ' Uğraşılacak iş. Meşguliyet.'),
(55130, 'U1', 'ÜŞGUR', 'üşgur', ' f. Oklu kirpi.'),
(55131, 'U1', 'ÜŞHUB', 'üşhub', ' Süt sağılırken çıkan ses.'),
(55132, 'U1', 'ÜŞKUFE', 'üşkufe', ' f. Çiçek.'),
(55133, 'U1', 'ÜŞKUH', 'üşkuh', ' f. Ululuk, büyüklük, şan ü şeref.'),
(55134, 'U1', 'ÜŞKÜFTE', 'üşküfte', ' f. Açılmış çiçek.'),
(55135, 'U1', 'ÜŞKÜR', 'üşkür', ' Mest içine dikilen astar.'),
(55136, 'U1', 'ÜŞNE', 'üşne', ' Yosun.'),
(55137, 'U1', 'ÜŞTÜLÜM', 'üştülüm', ' f. Kavga, gürültü.'),
(55138, 'U1', 'ÜŞTÜLÜMKÂR', 'üştülümkar', ' f. Kavgacı, gürültücü.'),
(55139, 'U1', 'ÜŞTÜR', 'üştür', ' f. Deve.'),
(55140, 'U1', 'ÜŞTÜRBÂN', 'üştürban', ' f. Deveci.'),
(55141, 'U1', 'ÜŞTÜRDİL', 'üştürdil', ' f. Kinci, fesatçı, hasedçi.'),
(55142, 'U1', 'ÜŞTÜREK', 'üştürek', ' f. Dalga. Mevc.'),
(55143, 'U1', 'ÜŞTÜRGAV', 'üştürgav', ' f. Zürafa.'),
(55144, 'U1', 'ÜŞTÜRHU', 'üştürhu', ' f. Deve huylu. Kinci, hased eden.'),
(55145, 'U1', 'ÜŞTÜRMURG', 'üştürmurg', ' f. Deve kuşu.'),
(55146, 'U1', 'ÜTAM', 'ütam', ' Sidik tutulması. İdrar tutukluğu.'),
(55147, 'U1', 'ÜTRUR', 'ütrur', ' Subaşı oğlanı.'),
(55148, 'U1', 'ÜVAM', 'üvam', ' Susuzluk.'),
(55149, 'U1', 'ÜVERA''', 'üvera''', ' Ateş ve güneş harareti. * Susuzluk harareti.'),
(55150, 'U1', 'ÜVEYL', 'üveyl', ' Çığlık, vâveylâ.'),
(55151, 'U1', 'ÜVEYS-EL KARANÎ', 'üveys-el karani', ' Hz. Ebu Bekir ve Ömer (R.A.) devirlerinde Medine-i Münevvere''de çok hürmet gören ve Tabiînin büyüklerinden olup hadis-i şerif ile medh ü senâsı yapılan büyük bir veli. Peygamberimiz (A.S.M.) zamanında yaşamış ise de vâlidesine çok hürmetinden dolayı Peygamberimizle görüşememiş, fakat ona bütün ruh u canı ile bağlı kalmıştır. Sıffîn Muharebesinde Hz. Ali''nin (R.A.) askerleri arasında şehid düşmüştü. (Hi: 37) Veys diye de anılır.'),
(55152, 'U1', 'ÜVEYSÎ', 'üveysi', ' (Üveysî tarzı) Veysel Karanî Hazretleri gibi sevdiği ve kendisine bağlı olduğu zatı görmeden ve gaybî olarak olan muhabbet ve bağlılık; ve bu muhabbetle bağlı olduğu zattan manevî feyz almak tarzı.'),
(55153, 'U1', 'ÜYEL', 'üyel', ' (C: Eyâyil) Dağ keçisi.'),
(55154, 'U1', 'ÜZANİ', 'üzani', ' Kulakları büyük olan adam. (Merkepten kinaye olarak söylenmiştir.)'),
(55155, 'U1', 'ÜZEYR', 'üzeyr', ' (A.S.) Kur''an-ı Kerim''de ismi bulunan büyük zâtlardandır. Peygamber olup olmadığı hakkında ihtilâf vardır.'),
(55156, 'U1', 'ÜZFUR', 'üzfur', ' (C.: Ezfâr-Ezâfir) Tırnak.'),
(55157, 'U1', 'ÜZLUFE', 'üzlufe', ' (C.: Ezâlif) Sarp kayalı yer.'),
(55158, 'U1', 'ÜZN', 'üzn', ' Kulak. İşitme organı.'),
(55159, 'U1', 'ÜZN-Ü DÂHİLÎ', 'üzn-ü dahili', ' İç kulak.'),
(55160, 'U1', 'ÜZUF', 'üzuf', ' Yakın olmak, yaklaşmak.'),
(55161, 'U1', 'ÜMİDBAHŞ', 'ümidbahş', 'f. Ümitlendiren, ümit veren. '),
(55162, 'U1', 'ÜNŞUDE', 'ünşude', '(Bak: Neşide) '),
(55163, 'U1', 'ÜSRUŞ', 'üsruş', 'f. Güzel ses. '),
(55164, 'U1', 'ÜŞBE', 'üşbe', 'Kurt, böcek. '),
(55165, 'U1', 'ÜŞER', 'üşer', 'Dişlerini birbirine sürüp keskinleştirmek. '),
(55166, 'U1', 'ÜŞGUR', 'üşgur', 'f. Oklu kirpi. '),
(55167, 'U1', 'ÜŞKUFE', 'üşkufe', 'f. Çiçek. '),
(55168, 'U1', 'ÜŞKUH', 'üşkuh', 'f. Ululuk, büyüklük, şan ü şeref. '),
(55169, 'U1', 'ÜŞKÜR', 'üşkür', 'Mest içine dikilen astar. '),
(55170, 'U1', 'ÜŞNE', 'üşne', 'Yosun. '),
(55171, 'U1', 'ÜŞTÜLÜM', 'üştülüm', 'f. Kavga, gürültü. '),
(55172, 'U1', 'ÜŞTÜR', 'üştür', 'f. Deve. '),
(55173, 'U1', 'ÜŞTÜRBÂN', 'üştürban', 'f. Deveci. '),
(55174, 'U1', 'ÜŞTÜREK', 'üştürek', 'f. Dalga. Mevc. '),
(55175, 'U1', 'ÜŞTÜRGAV', 'üştürgav', 'f. Zürafa. '),
(55176, 'U1', 'ÜŞTÜRHU', 'üştürhu', 'f. Deve huylu. Kinci, hased eden. '),
(55177, 'U1', 'ÜŞTÜRMURG', 'üştürmurg', 'f. Deve kuşu. '),
(55178, 'V0', 'VA', 'va', ' f. "Arkada, geri" mânâlarına gelerek birleşik kelimeler yapar.'),
(55179, 'V0', 'VA', 'va', ' "Vah, yazık" meâlinde olup hayf, hasret, esef gibi kelimelerle birlikte söylenir. (Buna Arabçada "edât-ı nüdbe" denir.)Türkçede bunun yerine; vâh, vây, eyvâh edatları kullanılır. Bunlar bâzan şiddet ve te''yid için tekrar edilir.'),
(55180, 'V0', 'VA''', 'va''', ' Çakal.'),
(55181, 'V0', 'VAAD', 'vaad', ' (Bak: Va''d)'),
(55182, 'V0', 'VAAZ', 'vaaz', ' (Bak: Va''z)'),
(55183, 'V0', 'VA''B', 'va''b', ' Ulaştırmak, vardırmak. * Toplamak, cem''etmek.'),
(55184, 'V0', 'VABESTE', 'vabeste', ' f. Bağlı, mütevakkıf, olması bir şeye bağlı olan.(Bir fikre davet, cumhur-u ulemanın kabulüne vabestedir. M.)'),
(55185, 'V0', 'VABİL', 'vabil', ' Yağmur. İri katreli yağmur.'),
(55186, 'V0', 'VÂCİB', 'vacib', ' (Vücub. dan) (C.: Vâcibât) Lüzumlu, mecburi olan. * Fık: Yerine getirilmesi her müslüman için gerekli ve borç olup, yapılmadığı takdirde büyük günah olan Allah''ın emirleri. Yapılması zannî delil ile belli olan. Terki câiz olmayan. Yapılması şer''an kat''i derecede bir delil ile sâbit olmamakla beraber, her halde pek kuvvetli bir delil ile sâbit bulunan şeydir. (Vitir ve Bayram namazları gibi.) * İlm-i Kelâm''da: Varlığı zaruri olup, olmaması imkânsız bulunan.'),
(55187, 'V0', 'VÂCİB-ÜL İFA', 'vacib-ül ifa', ' İfa edilmesi lüzumlu olan. Yapılması gerekli olan.'),
(55188, 'V0', 'VÂCİB-ÜL VÜCUD', 'vacib-ül vücud', ' Vücudu mutlak var olan, yokluğu mümkün olmayan Cenâb-ı Hak.(Vâcib-ül vücuddur, yâni; O''nun vücudu zâtîdir, ezelîdir, ebedîdir, ademi mümteni''dir. Zevali muhaldir. Tabakat-ı vücudun en râsihi, en esaslısı, en kuvvetlisi, en mükemmelidir. Sair tabakat-ı vücud O''nun vücuduna nisbeten gayet zayıf bir gölge hükmündedir. M.) (Bak: Kıyam-ı binefsihî, Vücud)'),
(55189, 'V0', 'VÂCİBÂT', 'vacibat', ' (Vâcibe. C.) Yapılması lüzumlu olan şeyler. Vâcib olan şeyler.'),
(55190, 'V0', 'VÂCİBE', 'vacibe', ' Yapılıp yerine getirilmesi vâcib derecesinde lüzumlu olan şey.'),
(55191, 'V0', 'VACİD(E)', 'vacid(e)', ' Vücuda getiren. * Varlıklı. Fâtır. Gani ve zengin. * Mevcud olan.'),
(55192, 'V0', 'VACİFE', 'vacife', ' Muztarib olan. Istırab çeken. Korkan. * Sallana sallana yürüyen.'),
(55193, 'V0', 'VACİZ(E)', 'vaciz(e)', ' Kısa.'),
(55194, 'V0', 'VA''D', 'va''d', ' Söz verme. Söz verilen şey. Bir kimsenin yapacağına veya yapmayacağına dâir söz vermiş olduğu husus. Bir şeyi yapmak veya bir şey için söz vermek va''ddır. Hayır işlenecek iş için masdar "va''d" veya "vaide" dir. İşlenecek şey şer ise; ev''ide denir. Masdarı "Îâd: $ " dır. Va''d hayırda, îâd ve vaîd şerde kullanıldığına göre; vaîd: $ masdarı şerre niyet ettiğini, korkulacak iş işleyeceğini haber vermekle korkutmaktan ibarettir.'),
(55195, 'V0', 'VAD', 'vad', ' f. Oğul.'),
(55196, 'V0', 'VADADE', 'vadade', ' f. Reddolunmuş, geri çevrilmiş. Merdud.'),
(55197, 'V0', 'VA''DE', 'va''de', ' Bir iş için önceden belli edilen zaman. Bir işi te''hir etmek, sonraya bırakmak için olan belli vakit. * Ecel.'),
(55198, 'V0', 'VADİ', 'vadi', ' İki dağ arasındaki uzun çukur. Dere. Bir nehrin aktığı yer. Nehir yatağı. * Yol, tarz, usül. * Saha.'),
(55199, 'V0', 'VADİ-İ HÂMUŞAN', 'vadi-i hamuşan', ' Kabristan, mezarlık.'),
(55200, 'V0', 'VADK', 'vadk', ' Yağmur damlamak. * Alışmak. * Yağmur. * Genişlik. * Kolaylaştırmak, yakın olmak.'),
(55201, 'V0', 'VA ESEFA', 'va esefa', ' Vah, esefler olsun! Eyvah, çok yazık!'),
(55202, 'V0', 'VÂFİ(YE)', 'vafi(ye)', ' (Vefâ. dan) Tam, elverişli, kâfi, yeter. * Sözünün eri. * Va''dini mutlak yerine getiren Cenab-ı Hak.'),
(55203, 'V0', 'VÂFİ VE KÂFİ', 'vafi ve kafi', ' Bol bol yeter.'),
(55204, 'V0', 'VAFİD', 'vafid', ' (C.: Vüffed - Evfâd - Vüfud) Elçi, temsilci.'),
(55205, 'V0', 'VAFİH', 'vafih', ' Kilise kayyımı.'),
(55206, 'V0', 'VAFİR(E)', 'vafir(e)', ' (Vefret. den) Bir çok, bol, çok. * Edb: Aruz kalıplarından bahr-ı rabi''nin ismidir.'),
(55207, 'V0', 'VAFTİZ', 'vaftiz', ' (Vaftis) (Rumcadan) Hristiyanlarca çocuğun ve hristiyanlığa yeni girenin dine girme şartı sayılan, suya sokma merasimi. (Bak: Ta''mid)'),
(55208, 'V0', 'VAGD', 'vagd', ' Tamahkâr, cimri, hasis. * Alçak, bayağı, âdi.'),
(55209, 'V0', 'VAHA', 'vaha', ' Çöl ortasında suyu ve yeşilliği olan yer.'),
(55210, 'V0', 'VAHAL', 'vahal', ' (C.: Evhâl, vuhul) Bataklık, batak çamurlu yer. (Bak: Vahl)'),
(55211, 'V0', 'VAHAMA', 'vahama', ' (Vahim. C.) Tehlikeli, korkulu ve vahim olan şeyler.'),
(55212, 'V0', 'VAHAMET', 'vahamet', ' Zor, güçlük. * Ağırlık. Tehlike. Muhatara. Neticesi fena. * Hazım güçlüğü, sindirim zorluğu. * Korkulacak hal, tehlikeli vaziyet.'),
(55213, 'V0', 'VA HASRETA', 'va hasreta', ' Vah vah! Ne yazık ki! (Teessür bildirir.)'),
(55214, 'V0', 'VAHAT', 'vahat', ' Çöl ortasında yeşillik ve suyu olan yerler. Vâhalar.'),
(55215, 'V0', 'VAHAYFA', 'vahayfa', ' Eyvah, yazık.'),
(55216, 'V0', 'VAHDANÎ', 'vahdani', ' Allah''ın birliği ile alâkalı.'),
(55217, 'V0', 'VAHDANİYET', 'vahdaniyet', ' Birlik, infirad. Benzeri olmamak. Artmaktan, ayrılmaktan, eksilmekten beri ve münezzeh olmak gibi mânaları ifade eden Allah''ın bir sıfatıdır. Bu sıfatla muttasıf olana Vâhid denir ki; benzeri olmayan; tecezziden, tekessürden beri olan zât demektir.'),
(55218, 'V0', 'VAHDEDDİN', 'vahdeddin', ' (Aslı: Vahîdüddin, fakat Türkçede Vahdeddin şeklinde telâffuz edilir.) (Bak: Vahîd) Osmanlı Padişahlarının sonuncusu ve otuzaltıncısının adıdır. (Mi: 1861-1926) Zeki, dirayetli ve dindardı. Osmanlılar ve İslâm âlemi için bir felâket işareti olan Sevr Muahedesini imzalamadı. Osmanlı ordusu olarak emrine bırakılan yegâne taburu Ayasofya Câmii etrafında sipere sokup câmiye çan takmak isteyenlere "Ateş edin" diye emir vermişti. İtimad ettiği paşaları Anadolu''ya gönderip Milli Kurtuluş hareketini hazırlamıştı. Böyleyken İtalya''da vefat etti ve sonra Şam''da Sultan Selim Câmii kabristanına defnedildi. (R. Aleyh)'),
(55219, 'V0', 'VAHDET', 'vahdet', ' Birlik. Yalnızlık. Teklik. (Kesretin zıddıdır.) * Edb: İfade esnasında mevzuun haricine çıkılmaması, maksad ne ise yalnız ondan bahsedilmesi, sözün dallandırılıp budaklandırılmaması. * Tas: Allah''a yakınlık. Gönlünü, kalbini tamamen Allah ile meşgul etme hali.(Yüsr-ü vahdet; yâni birlik usulüyle bir merkezde, bir elden, bir kanunla olan işler; gayet derecede kolaylık veriyor. Müteaddit merkezlerde, müteaddit kanuna, müteaddit ellere dağılsa müşkilât peyda eder. M.)'),
(55220, 'V0', 'VAHDET-ÜL VÜCUD', 'vahdet-ül vücud', ' (Vahdet-üş şuhud) Her yerde ve herşeyde kalbini yalnız Allah ile meşgul etme hali ve yaşayışıdır. (Bu mesele hakiki olarak ancak veraset-i nübüvvet muhakkikleri olan müceddid ve asfiyaların tarifleriyle anlaşılabilir.)(Aziz kardeşim;Vahdet-ül vücuda dair bir parça izahat istiyorsunuz. Bu mes''eleye dair Otuz Birinci Mektubun bir Lem''asında, Hazret-i Muhyiddin''in bu mes''eledeki fikrine karşı gayet kuvvetli ve izahlı bir cevab vardır. Şimdilik bu kadar deriz ki:Bu mes''ele-i vahdet-ül vücudu şimdiki insanlara telkin etmek, ciddi zarar verir. Nasıl ki teşbihat ve temsiller, havassın elinden avamın eline ve ilmin elinden cehlin eline girse, hakikat telâkki edilir. (Hâşiye) Öyle de: Vahdet-ül vücud mes''elesi gibi hakaik-ı ulviye, ehl-i gaflet ve esbab içine dalan avamlara girse, tabiat telâkki edilir ve üç mühim zarar verir:Birincisi: Vahdet-ül vücudun meşrebi, Cenab-ı Hak hesabına kâinatı âdeta inkâr etmek iken; avama girdikçe, gafil avamlara, hususan maddiyyun fikirleriyle âlude olan fikirlere girdikçe, kâinat ve maddiyat hesabına uluhiyeti inkâr yoluna gider.İkincisi: Vahdet-ül vücud meşrebi, mâsivâ-yı İlâhînin rububiyetini o derece şiddetle reddeder ki, mâsivâyı inkâr ve ikiliği ref''ediyor. Değil nüfus-u emmarenin, belki herbir şeyin müstakil vücudunu görmemek iken, bu zamanda fikr-i tabiatın istilâsiyle ve gurur ve enaniyetin nefs-i emmareyi şişirmesiyle ve âhireti ve Hâlik''ı bir derece unutmak cihetiyle; bazı nüfus-u emmare küçük birer firavun, âdeta nefsini mabud ittihaz etmek istidadında bulunan insanlara vahdet-ül vücudu telkin etmek, nefs-i emmareyi el-iyazübillâh öyle şımartır ki, ele avuca sığmaz.Üçüncüsü: Tegayyür, tebeddül, tecezzi, tahayyüzden mukaddes, münezzeh, müberra, muallâ olan Zât-ı Zülcelâl''in vücub-u vücuduna ve tekaddüs ve tenezzühüne muvafık düşmeyen tasavvurata sebebiyet verir ve telkinat-ı bâtılaya medar olur. Evet vahdet-ül vücuddan bahseden; fikren serâdan Süreyya''ya çıkarak, kâinatı arkasında bırakıp nazarını Arş-ı Alâ''ya diken, istigrakî bir surette kâinatı ma''dum sayıp herşeyi doğrudan doğruya kuvvet-i iman ile Vâhid-i Ehad''den görebilir. Yoksa kâinatın arkasında durup kâinata bakan ve önünde esbabı gören ve ferşten nazar eden, elbette esbab içinde boğulup, tabiat bataklığına düşmek ihtimali var. Fikren Arş''a çıkan, Celâleddin-i Rumî gibi, diyebilir: "Kulağını aç! Herkesten işittiğin sözleri, fıtrî fonoğraflar gibi Cenab-ı Hak''tan işitebilirsin." Yoksa, Celâleddin gibi bu derece yükseğe çıkamayan ve ferşten Arş''a kadar mevcudatı âyine şeklinde görmeyen adama, "Kulak ver, herkesten Kelâmullah''ı işitirsin." desen, mânen Arş''tan ferşe sukut eder gibi, hilaf-ı hakikat tasavvurat-ı bâtılaya giriftar olur! L.)(Haşiye): Nasıl ki iki melâike, teşbihin sırr-ı münasebetiyle Sevr ve Hut tesmiye edilen, avamca koca bir öküz ve koca bir balık telâkki edilmiştir.'),
(55221, 'V0', 'VAHDET-ÂRÂM', 'vahdet-aram', ' f. Dinlendirici, rahat yer.'),
(55222, 'V0', 'VAHDET-GÂH', 'vahdet-gah', ' f. Yalnız kalınacak yer.'),
(55223, 'V0', 'VAHDET-GÜZİN', 'vahdet-güzin', ' f. Yalnızlığa çekilen.'),
(55224, 'V0', 'VAHDET-NÜMÂ', 'vahdet-nüma', ' Vahdet gösteren, birlik ifade eden.'),
(55225, 'V0', 'VAHHABÎ', 'vahhabi', ' (Bak: Vehhabî)'),
(55226, 'V0', 'VAHİ', 'vahi', ' Mânâsız, saçma. Ehemmiyetsiz. * Ahmak. Düşkün. Zaif.'),
(55227, 'V0', 'VAHİYÂT', 'vahiyat', ' (Vâhiye. C.) Mânasız, faydasız ve ehemmiyetsiz şeyler.'),
(55228, 'V0', 'VÂHİB', 'vahib', ' (Vâhibe) Bağışlayan, veren, ihsan eden, hibe eden.'),
(55229, 'V0', 'VÂHİB-ÜL ATÂYÂ', 'vahib-ül ataya', ' Hediyeler bağışlayan. Bağışlar ihsan eden. (Cenab-ı Hak (C.C.) '),
(55230, 'V0', 'VÂHİB-ÜL HAYAT', 'vahib-ül hayat', ' Hayatı bağışlayan, hayat veren Allah (C.C.).'),
(55231, 'V0', 'VÂHİD', 'vahid', ' Bir, tek, biricik. Eşi, benzeri, cüz''ü, parçası olmayan Allah (C.C.) Ferid.'),
(55232, 'V0', 'VÂHİD-İ İ''TİBARÎ', 'vahid-i i''tibari', ' Hakikatta olmayıp varlığı farazî olarak kabul edilen bir şey. Varlığına itibar edilen şey. (Ağırlık için kilo, uzunluk için metre bir vâhid-i itibarîdir.)'),
(55233, 'V0', 'VÂHİD-İ KIYASÎ', 'vahid-i kıyasi', ' Bir şeyin miktarını ve sair hususiyetlerini ölçmek için kendi cinsinden değişmez olarak tayin edilen parça veya miktar. Meselâ: Uzunluğun "vâhid-i kıyasîsi" metredir. Hava tazyiklerinin ve sıcaklıklarınınki de derecedir.'),
(55234, 'V0', 'VAHÎD', 'vahid', ' Yalnız, tek. * Hz. Peygamber''in de (A.S.M.) bir ismidir. Benzeri bulunmayan, hiçbir mahlukla müsavi olmayan ve tek olan (meâlindedir).'),
(55235, 'V0', 'VAHÎD-ÜD DEHR', 'vahid-üd dehr', ' (Vahîd-üz zaman) Zamanın, devrin eşi bulunmaz tek insanı.'),
(55236, 'V0', 'VÂHİDEN', 'vahiden', ' Vâhid olarak. Tek olarak.'),
(55237, 'V0', 'VÂHİDİYYET', 'vahidiyyet', ' Cenab-ı Hakk''ın (C.C.) umum eşyada birden birlik tecellisi.(Vâhidiyyet ise, bütün o mevcudat birinindir ve birine bakar ve birinin icadıdır, demektir. Ehadiyyet ise, herbir şeyde Hâlık-ı Küll-i Şey''in ekser esması tecelli ediyor demektir. Meselâ: Güneşin ziyası bütün zeminin yüzünü ihata ettiği haysiyetiyle vâhidiyet misalini gösterir. Ve herbir şeffaf cüzde ve su katrelerinde Güneş''in ziyası ve harareti ve ziyasındaki yedi rengi ve bir nevi gölgesi bulunması ehadiyyet misalini gösterir. Ve herbir şeyde, hususan zihayatta ve bilhassa herbir insanda o Sâni''in ekser esması tecelli ettiği cihetle ehadiyyeti gösterir. M.) (Bak: Ehadiyyet, Rahmaniyyet, Rabb-ül erbab)'),
(55238, 'V0', 'VAHİM', 'vahim', ' Ağır. * Sonu tehlikeli. Çok korkulu. * Hazmı güç olan. Zararlı veya faydalı olmayan yemek.'),
(55239, 'V0', 'VAHİM(E)', 'vahim(e)', ' (Vehm. den) Vehmeden, kuran, kuruntulu.'),
(55240, 'V0', 'VAHİME', 'vahime', ' Vehim veren, vesvese veren.'),
(55241, 'V0', 'VAHİN', 'vahin', ' Zayıf kimse.'),
(55242, 'V0', 'VAHİNE', 'vahine', ' İyeği kemiklerinin kısaları.'),
(55243, 'V0', 'VAHİR', 'vahir', ' İğne. * Diken.'),
(55244, 'V0', 'VAHİY', 'vahiy', ' Bir fikrin, bir hakikatın veya emrin Allah (C.C.) tarafından Peygambere bildirilmesi. * Lügatte vahiy: Kelâm, kitap, işaret, irsal, ilham, ifham, emir, teshir, bir şeyi harfiyyen i''lâm, bazı hususi maksadları tebliğ gibi mânalara gelir. * Şeriatta vahiy: Dilediği ahkâmı, esrar ve hakaikı Peygamberan-ı Zişanına rüya, ilham, kitap, irsal-i melek yollarından biriyle Cenab-ı Hakk''ın bildirip ifham buyurması demektir.(Vahiy ve ilhamın farkları: Birincisi: İlhamdan çok yüksek olan vahyin ekserisi melâike vasıtası ile ve ilhamın ekserisi vasıtasız olmasıdır. Meselâ: Nasıl ki, bir padişahın iki suretle konuşması ve emirleri var. Birisi: Haşmet-i saltanat ve hâkimiyyet-i umumiyye haysiyetiyle bir yâverini bir vâliye gönderir. O hâkimiyetin ihtişamını ve emrin ehemmiyetini göstermek için bazan vasıta ile beraber bir içtima yapar. Sonra ferman tebliğ edilir.İkincisi: Sultanlık ünvanı ile ve padişahlık umumi ismiyle değil, belki kendi şahsı ile hususi bir münasebeti ve cüz''î bir muamelesi bulunan has bir hizmetçisi ile veya bir âmi raiyyetiyle, hususi telefonu ile hususi konuşmasıdır. Öyle de Padişah-ı Ezelî''nin umum âlemlerin rabbi ismiyle ve kâinat Hâlıkı ünvanı ile vahy ile ve vahyin hizmetini gören şümullü ilhamları ile mükâlemesi olduğu gibi; her bir ferdin, her bir zihayatın Rabbi ve Hâlıkı olmak haysiyetiyle hususi bir surette fakat perdeler arkasında onların kabiliyyetine göre bir tarz-ı mükâlemesi var.İkinci fark: Vahiy gölgesizdir, safidir, havassa hastır. İlham ise; gölgelidir, renkler karışır, umumidir. Melâike ilhamları ve insan ilhamları ve hayvanat ilhamları gibi çeşit çeşit, hem pekçok envaiyle denizlerin katreleri kadar kelimat-ı Rabbâniyenin teksirine medar bir zemin teşkil ediyor. Ş.)(Vahiy iki kısımdır:Biri: "Vahy-i Sarihî" dir ki, Resul-i Ekrem (A.S.M.) onda sırf bir tercümandır, mübelliğdir, müdahalesi yoktur. Kur''an ve bazı ehadis-i kudsiye gibi.İkinci kısım: "Vahy-i Zımnî" dir. Şu kısmın mücmel ve hülâsası, vahye ve ilhama istinad eder; fakat tafsilâtı ve tasviratı, Resul-i Ekrem Aleyhissalâtü Vesselâm''a aittir. O vahiyden gelen mücmel hâdiseyi tafsil ve tasvirde Zât-ı Ahmediye Aleyhissalâtü Vesselâm, bazan yine ilhama, ya vahye istinad edip beyan eder; veyahut kendi ferasetiyle beyan eder. Ve kendi içtihadiyle yaptığı tafsilât ve tasviratı ya vazife-i risalet noktasında ulvi kuvve-i kudsiye ile beyan eder veyahut örf ve âdet ve efkâr-ı âmme seviyesine göre, beşeriyeti noktasında beyan eder.İşte her hadiste bütün tafsilâtına, vahy-i mahz noktasıyla bakılmaz. Beşeriyetin muktezası olan efkâr ve muamelâtında, risaletin ulvi âsârı aranılmaz. Mâdem bazı hâdiseler mücmel olarak mutlak bir surette O''na vahyen gelir, o da kendi ferasetiyle ve teârüf-ü umumi cihetiyle tasvir eder. Şu tasvirdeki müteşabihata ve müşkilâta bazan tefsir lâzım geliyor, hattâ tabir lâzım geliyor. Çünki bazı hakikatlar var ki, temsil ile fehme takrib edilir. Nasıl ki bir vakit huzur-u Nebevîde derince bir gürültü işitildi. Ferman etti ki: "Şu gürültü, yetmiş senedir yuvarlanıp, şimdi Cehennem''in dibine düşmüş bir taşın gürültüsüdür." Bir saat sonra cevap geldi ki: "Yetmiş yaşına giren meşhur bir münafık ölüp, Cehennem''e gitti." Zât-ı Ahmediye Aleyhissalâtü Vesselâm''ın beliğ bir temsil ile beyan ettiği hâdisenin te''vilini gösterdi. M.)'),
(55245, 'V0', 'VAHİYE', 'vahiye', ' (Bak: Vahi)'),
(55246, 'V0', 'VAHL', 'vahl', ' Sıvı çamur. Balçık. Tîn-i rakik.'),
(55247, 'V0', 'VAHL-GÂH', 'vahl-gah', ' f. Bataklık.'),
(55248, 'V0', 'VAHŞ', 'vahş', ' (C.: Vuhuş - Vahşân) İnsandan kaçan, yabani ve ürkek hayvan. * Tenha ve ıssız yer.'),
(55249, 'V0', 'VAHŞÂN', 'vahşan', ' (Vahş. C.) Issız, tenha yerler. * Yabani hayvanlar.'),
(55250, 'V0', 'VAHŞET', 'vahşet', ' (Vahş - Vahiş) Yabanilik. * Issızlık, tenhalık. * Vehim, ürküntü. Korku. Vahşilik. * Tenha, ıssız, korkunç yer. * Elbise ve silâhını çıkarıp atmak. * Aç kimse.'),
(55251, 'V0', 'VAHŞET-ÂBÂD', 'vahşet-abad', ' f. Issız, korku ve ürkeklik veren yer.'),
(55252, 'V0', 'VAHŞET-ÂGİN', 'vahşet-agin', ' Çok ıssız, korkulu yer, korkunç.'),
(55253, 'V0', 'VAHŞET-ÂMİZ', 'vahşet-amiz', ' f. Vahşetle karışık.'),
(55254, 'V0', 'VAHŞET-ÂVER', 'vahşet-aver', ' f. Korku veren, ürküten.'),
(55255, 'V0', 'VAHŞET-ENGİZ', 'vahşet-engiz', ' f. Korkulu.'),
(55256, 'V0', 'VAHŞET-GÂH', 'vahşet-gah', ' f. Korku yeri. Issız yer.'),
(55257, 'V0', 'VAHŞET-NÂK', 'vahşet-nak', ' f. Korku veren yer. Issız ve korkulu yer.'),
(55258, 'V0', 'VAHŞET-ZÂR', 'vahşet-zar', ' f. Yabani, ıssız yer.'),
(55259, 'V0', 'VAHŞİ(YE)', 'vahşi(ye)', ' Medeni olmayan. İnsanlardan kaçan. Alışık ve ehlî olmayan. * Merhametsiz, duygusuz. * Ürkek, korkak.'),
(55260, 'V0', 'VAHŞİYÂNE', 'vahşiyane', ' Vahşice. Vahşiye yakışır şekilde.'),
(55261, 'V0', 'VAHŞUR', 'vahşur', ' f. Peygamber, nebi.'),
(55262, 'V0', 'VAHY', 'vahy', ' (Bak: Vahiy)'),
(55263, 'V0', 'VAHY-İ MAHZ', 'vahy-i mahz', ' Kuvvetli ve sarih mertebede olan vahiy. Sırf vahiy olup, içinde Allah''ın bildirdiğinden başka bir şey katılmamış vahiy.'),
(55264, 'V0', 'VAHY-İ SARİHÎ', 'vahy-i sarihi', ' Hem sözü, hem mânası tam vahiy olan. (Âyetler ve kudsi hadisler gibi) Resul-ü Ekrem burada sırf tebliğ edendir. Müdahalesi yoktur.'),
(55265, 'V0', 'VAHY-İ SEMAVÎ', 'vahy-i semavi', ' Beşerin düşünerek yapmasına inkân olmayan, Allah (C.C.) tarafından melek vasıtasıyla Peygambere gönderilen vahiy.'),
(55266, 'V0', 'VAHY-İ ZIMNÎ', 'vahy-i zımni', ' Mücmel ve hulâsası vahye ve ilhama istinad eden; tasvirât ve tafsilatı Resul-ü Ekrem''e (A.S.M.) âit olan vahiydir.'),
(55267, 'V0', 'VAHZ', 'vahz', ' Sivri bir şey batırarak acıtma. * Çimdikleme. * Isırma. * Sokma.'),
(55268, 'V0', 'VAÎ', 'vai', ' (C: Vuât) Hâfız.'),
(55269, 'V0', 'VAÎD', 'vaid', ' İyiliğe sevk veya kötülükten kurtarmak için ileride olacak kat''i hâdiseleri haber vererek korkutmak. * Cehennemi haber vermek. (Bak: Va''d)'),
(55270, 'V0', 'VAİF', 'vaif', ' Davar yürüdüğünde karnından işitilen ses.'),
(55271, 'V0', 'VÂİZ', 'vaiz', ' Nasihat veren. Dinî mes''eleler üzerinde öğüt veren.(Ben vâizleri dinledim. Nasihatları bana tesir etmedi. Düşündüm. Kasavet-i kalbimden başka üç sebep buldum:Birincisi: Zaman-ı hâzırayı zaman-ı sâlifeye kıyas ederek yalnız tasvir-i müddeâyı parlak ve mübalâğalı gösteriyorlar. Tesir ettirmek için; isbat-ı müddea ve müteharri-i hakikatı ikna'' lâzım iken ihmal ediyorlar.İkincisi: Bir şeyi tergib veya terhib etmekle ondan daha mühim şeyi tenzil edeceklerinden muvazene-i Şeriatı muhafaza etmiyorlar.Üçüncüsü: Belâgatın muktezası olan hale mutabık, yani ilcâat-ı zamana muvafık, yani teşhis-i illete münasib söz söylemezler; güya insanları eski zaman köşelerine çekiyorlar, sonra konuşuyorlar.Hâsıl-ı kelâm: Büyük vâizlerimiz hem âlim-i muhakkik olmalı, tâ isbat ve iknâ etsin. Hem hakîm-i müdakkik olmalı, tâ muvazene-i Şeriatı bozmasın. Hem beliğ-i mukni'' olmalı, tâ mukteza-yı hal ve ilcâat-ı zamana muvafık söz söylesi ve mizan-ı Şeriatle tartsın. Ve böyle olmaları da şarttır. İk. M.) (Bak: Hissiyat)'),
(55272, 'V0', 'VAİZÎN', 'vaizin', ' (Vâizûn) Vâizler. Halka nasihat verenler.'),
(55273, 'V0', 'VAJGUN', 'vajgun', ' (Vâjgune) f. Ters, tersine dönmüş. Uğursuz.'),
(55274, 'V0', 'VAK''', 'vak''', ' Ağırbaşlılık. Ağırlık. * Yüksek yer.'),
(55275, 'V0', 'VA''K', 'va''k', ' Sıtma ve harareti.'),
(55276, 'V0', 'VAK''', 'vak''', ' Yüksek mekân. * Etki, tesir. * Düşmek.'),
(55277, 'V0', 'VA''K(A)', 'va''k(a)', ' Yaramaz huylu kişi.'),
(55278, 'V0', 'VAK''A', 'vak''a', ' Hâdise. Olup geçen şey. Mes''ele. * Birini bir defada yere düşürmek. * Muharebe. * Vuku bulan.'),
(55279, 'V0', 'VAK''A-İ HAYRİYE', 'vak''a-i hayriye', ' Tar: Yeniçeri Ocağı''nın kaldırılması münasebetiyle kullanılan bir tabirdir. İlk önceleri büyük hizmetleri görülen Yeniçeriler, zamanla nizam ve intizamlarını kaybettikleri gibi, son zamanlarda uygunsuz hareket ve isyanlarla memleketin başına belâ kesildikleri için, ocağın lağvı hayırlı sayılmış ve bu sebeple bu tabir meydana gelmiştir. (O.T.D.S.)'),
(55280, 'V0', 'VAKA''', 'vaka''', ' Yufka bulut. * Taş. * Yerin taşlı olmasından ayak incinmek. * Cefa, eza. * Vurma, darp.'),
(55281, 'V0', 'VAKAD', 'vakad', ' Alevlenen ateş.'),
(55282, 'V0', 'VAKAD', 'vakad', ' (Ateş) yanmak ve tutuşmak.'),
(55283, 'V0', 'VAKAH', 'vakah', ' Katı yüzlü, utanmaz, hayırsız kimse. * Sağlam ve sert tırnak.'),
(55284, 'V0', 'VAKAHAT', 'vakahat', ' Arsızlık. Utanmazlık. Katı yüzlülük. Açıklık ve saçıklık. * Pek sağlam ve metin.'),
(55285, 'V0', 'VAKAHET', 'vakahet', ' (Vakhe) İbadet, taat. * Bir adamın sözünü dinleyip itaat ve imtisal etmek, ona uymak. * Bir şeyi bırakıp feragat etmek. * Büyük papaz olmak.'),
(55286, 'V0', 'VAK''A-NÜVİS', 'vak''a-nüvis', ' f. Osmanlı İmparatorluğu devrinde, zamanın hâdiselerini kaydetmekle vazifeli olan resmi devlet tarihçisi.'),
(55287, 'V0', 'VAKAR', 'vakar', ' Ağırbaşlılık. Halim ve heybetli oluş. Nâmusu muhafazayı mucib haslet. Temkinlilik. Azamet ve izzet.'),
(55288, 'V0', 'VAKAS', 'vakas', ' Boynun kısa olması. Ateşe attıkları ufacık değnekler. * İki nisap zekâtın arasındaki zekâtı olmayan hayvanlar.'),
(55289, 'V0', 'VAKAYİ''', 'vakayi''', ' (Vak''a. C.) Vâki olup zuhur eden hususlar. * Kıtaller. Öldüresiye vuruşlar.'),
(55290, 'V0', 'VAKB (VÜKUB)', 'vakb (vükub)', ' Duhul etmek, dâhil olmak, girmek. * Kaybolmak.'),
(55291, 'V0', 'VAKD', 'vakd', ' (Vakdân) Ateşin yanması, tutuşması.'),
(55292, 'V0', 'VA''KE', 'va''ke', ' Cenk yeri, dövüş alanı.'),
(55293, 'V0', 'VAKF', 'vakf', ' Bir kimseyi veya bir şeyi alıkoymak, durdurmak. Kımıldatmamak. * Hareketten fariğ olmak, imsak etmek. Hapsetmek. Aslâ satılmamak, başka şeye tebdil olunmamak şartı ile bir mülkü Allah yoluna vermek. Menfaatı hayır nevilerinden birisine âit olmak üzere bir mülkü ilelebed vermek. * Tecvidde: Durmak ve durdurmak mânalarına gelerek, nefesle beraber sesin kesilmesine denir. Yâni: Kur''an-ı Kerimi tilâvet ederken herhangi bir kelime üzerinde bir müddet sesi kesip, nefes alarak dinlenme halidir.'),
(55294, 'V0', 'VAKF-I HAYAT', 'vakf-ı hayat', ' Hayatını vakfetme. * Ömrünü tamamen din hizmetine vermek.'),
(55295, 'V0', 'VAKFE', 'vakfe', ' Bir hareketin geçici olarak durdurulması. * Durak. Durulacak yer. * Hacıların Hac esnasında Arafat''taki tevakkufları olup, eda etmeğe mecbur oldukları şartlardan birisidir.'),
(55296, 'V0', 'VAKFE-İ HAYRET', 'vakfe-i hayret', ' Hayret duraklaması.'),
(55297, 'V0', 'VAKFEGÂH', 'vakfegah', ' f. Durak yeri.'),
(55298, 'V0', 'VAKFETMEK', 'vakfetmek', ' Fık: Bir malı veya bir şeyi bir işe bağlayıp o yolda devamlı kılmak. * Bir şeyi karşılıksız olarak Allah yoluna vermek.'),
(55299, 'V0', 'VAKFÎ', 'vakfi', ' Vakfa âit, vakıfla alâkalı.'),
(55300, 'V0', 'VAKFİYE', 'vakfiye', ' Mülkün vakıf olmak keyfiyyeti.'),
(55301, 'V0', 'VAKH (VEKAHE)', 'vakh (vekahe)', ' Taat, ibadet.'),
(55302, 'V0', 'VÂKIA''', 'vakıa''', ' Vuku bulmuş, olmuş, var olan mevcud bir hâdise. * Olan olmuş. * Rüya, düş. * şiddetli hâdise. * Meşakkat, musibet. * Kıyamet. * Cenk, savaş.'),
(55303, 'V0', 'VÂKIA SURESİ', 'vakıa suresi', ' Kur''an-ı Kerim''in 56. suresidir. Mekkîdir.'),
(55304, 'V0', 'VÂKIÂT', 'vakıat', ' (Vâkıa. C.) Vâkıalar. Baştan geçen hâdiseler.'),
(55305, 'V0', 'VÂKIF', 'vakıf', ' Bilen, haber sahibi. Aşina. Bir işten iyi haberi olan. * Vakfeden. * Duran, ayakta duran.'),
(55306, 'V0', 'VÂKIF-I AHVAL', 'vakıf-ı ahval', ' Durumdan haberli olan, işlere vâkıf bulunan.'),
(55307, 'V0', 'VÂKIF-I ESRAR', 'vakıf-ı esrar', ' Gizli şeyleri, sırları bilen.'),
(55308, 'V0', 'VÂKIFANE', 'vakıfane', ' f. Bilen kimseye yakışır surette, bilerek. Vâkıf şekilde. Anlamak ve bilmek suretiyle.');
INSERT INTO `db_lugat` (`id`, `indeks`, `kelime`, `kirpilmis`, `anlam`) VALUES
(55309, 'V0', 'VAKIYYE', 'vakıyye', ' Dörtyüz dirhemlik tartı.'),
(55310, 'V0', 'VÂKİ''', 'vaki''', ' Olan, düşen, konan. Mevcud ve var olan. * Geçmiş olan, geçen.'),
(55311, 'V0', 'VÂKİ-İ HÂL', 'vaki-i hal', ' Hâlin hakikatı, o işin hakikatı.'),
(55312, 'V0', 'VÂKÎ', 'vaki', ' (Vikaye. den) Saklayan, koruyan, vikaye eden, esirgeyen. * Önleyici tedbir veya ilaç.'),
(55313, 'V0', 'VAKÎA', 'vakia', ' Kıtal. Öldüresiye vuruşmak. * Vak''a.'),
(55314, 'V0', 'VÂKİB', 'vakib', ' Ayak üstüne duran kişi.'),
(55315, 'V0', 'VAKÎB', 'vakib', ' At yürürken karnı içinden işitilen ses.'),
(55316, 'V0', 'VAKÎH', 'vakih', ' Hayâsız, utanmaz, edepsiz.'),
(55317, 'V0', 'VAKİN', 'vakin', ' Oturucu, oturan.'),
(55318, 'V0', 'VAKİR', 'vakir', ' Yuvasına girmiş kuş.'),
(55319, 'V0', 'VAKKAS', 'vakkas', ' Okçu. İyi muharebe eden. Savaşçı.'),
(55320, 'V0', 'VAKL', 'vakl', ' Yükselmek. * Bir nesnenin üstüne çıkmak. * Mukul ağacı.'),
(55321, 'V0', 'VAKM', 'vakm', ' Reddetmek. * Hor ve zelil etmek.'),
(55322, 'V0', 'VAKNE', 'vakne', ' Her nesnenin azı.'),
(55323, 'V0', 'VAKR', 'vakr', ' Az işitmek. Sağırlık.'),
(55324, 'V0', 'VAKRE', 'vakre', ' Davarın tırnağının taşa dokunup sürçmesi.'),
(55325, 'V0', 'VAKS', 'vaks', ' Fahişe kısmının fahişeliğini zikrederek anlatmak. * Bedene uyuz illeti yayılması.'),
(55326, 'V0', 'VAKS', 'vaks', ' Boynu vurup kırmak.'),
(55327, 'V0', 'VAKŞ', 'vakş', ' His. * Hareket.'),
(55328, 'V0', 'VAKT', 'vakt', ' (Vakit) Zaman. Saat. Çağ. Mevsim. * Boş zaman. * Geçim. * Fırsat. * Muayyen, belli bir zaman.'),
(55329, 'V0', 'VAKT-İ ASR', 'vakt-i asr', ' İkindi vakti.'),
(55330, 'V0', 'VAKT-İ HÂCET', 'vakt-i hacet', ' İhtiyaç vakti. Lüzumlu vakit.'),
(55331, 'V0', 'VAKT-İ HAZAR', 'vakt-i hazar', ' Barış zamanı.'),
(55332, 'V0', 'VAKT-İ MERHUN', 'vakt-i merhun', ' Belli edilen, muayyen bir zaman.'),
(55333, 'V0', 'VAKT-İ TEFRİH', 'vakt-i tefrih', ' Tıb: Çiçek hastalığı aşısının yapılmasından te''sirini gösterinceye kadar geçen zaman.'),
(55334, 'V0', 'VAKT-İ ZEVAL', 'vakt-i zeval', ' Güneşin tam ortada, bize göre doğu ve batı ortasında bulunduğu ve gölgenin gündüzde en kısa olduğu zaman. Zeval vakti.'),
(55335, 'V0', 'VAKT', 'vakt', ' (C: Vikat) İçinde yağmur suyu biriken çukur. * Su ile faydalanacak mekân. * (Horoz) tavuğa binmek.'),
(55336, 'V0', 'VAKTAKİ', 'vaktaki', ' f. Ne vakit ki, o zaman ki, olduğu vakit.'),
(55337, 'V0', 'VAKTEN', 'vakten', ' Vakit ve zamanca.'),
(55338, 'V0', 'VAKUD', 'vakud', ' Odun, kömür gibi yakılacak şeyler.'),
(55339, 'V0', 'VAKUR', 'vakur', ' Ağırbaşlı, temkin sahibi. İzzetli, vakarlı.'),
(55340, 'V0', 'VAKURANE', 'vakurane', ' f. Ağırbaşlılıkla. Düşünce ve tedbirlilikle. Temkinle.'),
(55341, 'V0', 'VAKVAK', 'vakvak', ' Korkak kişi. * Hindistan''da Vakvak beldesinde yetişen bir ağaçtır. Yüz zira'' miktarı boyu olur, kalkan gibi yassı yaprağı olur.'),
(55342, 'V0', 'VAKVAKA', 'vakvaka', ' Kurbağa, tavuk, kuş sesi veya köpek havlaması.'),
(55343, 'V0', 'VAKZ', 'vakz', ' Galebe etmek. * Şiddetle vurup ölmeye yakın etmek.'),
(55344, 'V0', 'VAKZ', 'vakz', ' Sıklet, ağırlık.'),
(55345, 'V0', 'VA''L', 'va''l', ' Sığınacak yer.'),
(55346, 'V0', 'VÂLÂ', 'vala', ' Yüksek, âlî, refi''.'),
(55347, 'V0', 'VÂLÂCÂH', 'valacah', ' f. Mevkii yüce, rütbesi yüksek olan.'),
(55348, 'V0', 'VÂLÂKADD', 'valakadd', ' f. Boyu yüksek, uzun boylu.'),
(55349, 'V0', 'VÂLÂKADR', 'valakadr', ' f. Değeri yüksek, kadri yüce.'),
(55350, 'V0', 'VÂLÂŞÂN', 'valaşan', ' f. Şânı yüce.'),
(55351, 'V0', 'VÂLÂYÎ', 'valayi', ' f. Yücelik, yükseklik.'),
(55352, 'V0', 'VALİ', 'vali', ' Bir vilâyeti idare eden en büyük memur. * Mâlik.'),
(55353, 'V0', 'VALİB', 'valib', ' Ulaşıcı, ulaşan, varan. * Önüne doğru giden.'),
(55354, 'V0', 'VALİBE', 'valibe', ' Evvelki ekinin kökünden biten ekin.'),
(55355, 'V0', 'VALİCE', 'valice', ' İnsanı şiddetle tutan bir hastalık.'),
(55356, 'V0', 'VALİD', 'valid', ' (Vilâdet. den) Doğurtan. Baba.'),
(55357, 'V0', 'VALİDAN', 'validan', ' (Bak: Vâlideyn)'),
(55358, 'V0', 'VALİDAT', 'validat', ' (Vâlide. C.) Anneler. Vâlideler.'),
(55359, 'V0', 'VALİDE', 'valide', ' Ana. Doğuran.'),
(55360, 'V0', 'VALİDEYN', 'valideyn', ' Ana ile baba. Vâlidân de denir.(Peder ve valideyi, şefkat ile teçhiz eden ve seni onların merhametli elleriyle terbiye ettiren hikmet ve rahmet hesabına onlara hürmet ve muhabbet, Cenâb-ı Hakk''ın muhabbetine aittir. O muhabbet ve hürmet, şefkat, Lillâh için olduğuna alâmeti şudur ki: Onlar ihtiyar oldukları ve sana hiçbir faideleri kalmadığı ve seni zahmet ve meşakkate attıkları zaman, daha ziyade muhabbet ve şefkat etmektir. $âyeti: Beş mertebe hürmet ve şefkate evlâdı dâvet etmesi; Kur''an''ın nazarında valideynin hukukları ne kadar ehemmiyetli ve ukukları, ne derece çirkin olduğunu gösterir. Madem peder; kimseyi değil, yalnız veledinin kendinden daha ziyade iyi olmasını ister. Ona mukabil veled dahi, pedere karşı hak dâva edemez. Demek valideyn ve veled ortasında fıtraten sebeb-i münakaşa yok. Zira münakaşa, ya gıpta ve hasetten gelir. Pederde oğluna karşı o yok. Veya münakaşa haksızlıktan gelir. Veledin hakkı yoktur ki, pederine karşı hak dâva etsin. Pederini haksız görse de, ona isyan edemez. Demek; pederine isyan eden ve onu rencide eden, insan bozması bir canavardır. S.)'),
(55361, 'V0', 'VALİDİYYET', 'validiyyet', ' Annelik ve babalık vasfı.'),
(55362, 'V0', 'VÂLİH', 'valih', ' Keder ve hüzünle aklı gitmiş, şaşırmış, hayrette kalmış.'),
(55363, 'V0', 'VÂLİHÂNE', 'valihane', ' f. Şaşkınca.'),
(55364, 'V0', 'VÂLİHÎN', 'valihin', ' Hayrette kalanlar. Şaşıranlar. (Bak: Veleh)'),
(55365, 'V0', 'VALLAHİ', 'vallahi', ' Allah için, Allah hakkı için, Allah''a yemin ederim (meâlinde büyük yemin.)'),
(55366, 'V0', 'VAM', 'vam', ' f. Borç.'),
(55367, 'V0', 'VA-MANDE', 'va-mande', ' Geride kalmış.'),
(55368, 'V0', 'VAMCU', 'vamcu', ' f. Borç arayan.'),
(55369, 'V0', 'VAMDAR', 'vamdar', ' f. Borçlu.'),
(55370, 'V0', 'VAMHAH', 'vamhah', ' f. Alacaklı.'),
(55371, 'V0', 'VAMIK', 'vamık', ' Seven. Âşık, sevdalı. * Meşhur bir hikâyede Azra''nın âşığının ismi.'),
(55372, 'V0', 'VAMÎ', 'vami', ' f. Borçlu.'),
(55373, 'V0', 'VAMK', 'vamk', ' Sevme, muhabbet.'),
(55374, 'V0', 'VA''N', 'va''n', ' Sığınacak yer, melce''. * Ot yetişmeyen taşlık ve sert yapılı arazi.'),
(55375, 'V0', 'VAPESÎN', 'vapesin', ' (Va-pesin) f. En gerideki, en sondaki.'),
(55376, 'V0', 'VÂR', 'var', ' f. (Teşbih edatıdır) Gibi, ...li, kerre, def''a, sâhib, mâlik, lâyıklık (yerinde kullanılarak birleşik kelimeler yapılır). Meselâ: Melek-vâr : Melek gibi. Ümid-vâr: Ümidli.'),
(55377, 'V0', 'VA''R', 'va''r', ' (Va''ra) Sağlam yer, sert yer.'),
(55378, 'V0', 'VARA''', 'vara''', ' Haramdan ve yaramaz işlerden sakınmak.'),
(55379, 'V0', 'VARAKA', 'varaka', ' Tek yaprak hâlindeki kâğıt. * Nebât yaprağı. Maden yaprağı. Kitap yaprağı. * Hasis kimse. * Peygamberimize (A.S.M.) ilk vahyin geldiği sırada Hz. Hatice vâlidemizin (R.A.) hâdiseyi kendisine bildirdiği ve o zamanın meşhur bir âlimi olan Varaka İbn-i Nevfel''in adı.'),
(55380, 'V0', 'VARAKÎ', 'varaki', ' Yaprakla ilgili. * Yaprak biçiminde.'),
(55381, 'V0', 'VARAKKERDAN', 'varakkerdan', ' f. Boş ve faydasız işlerle uğraşan kimse.'),
(55382, 'V0', 'VARAKPARE', 'varakpare', ' f. Kâğıt parçası. * Küçük yaprak. Yaprak parçası. * Ehemmiyetsiz yazı, tezkere.'),
(55383, 'V0', 'VARDİYA', 'vardiya', ' İtl. Gemilerde beklenen nöbet. * Nöbet yeri. Nöbet beklenilen yer.'),
(55384, 'V0', 'VARESTE', 'vareste', ' f. Affedilmiş. Halâs bulmuş, kurtulmuş. * Rahat, serbest.'),
(55385, 'V0', 'VARESTEGÎ', 'varestegi', ' f. Kurtulma, halâs bulma. * Rahatlık, serbestlik. * İlişiksizlik.'),
(55386, 'V0', 'VARİ', 'vari', ' f. Benzer, gibi.'),
(55387, 'V0', 'VARİ', 'vari', ' Semiz et. * Vahşi hımar, yabani eşek.'),
(55388, 'V0', 'VÂRİD(E)', 'varid(e)', ' (Vürud. dan) Ulaşan, yetişen, gelen, erişen. Akla gelen. * Olan. Bir şey hakkında söylenip tatbik edilen. * Hâzır, nâzır. * Bahadır.'),
(55389, 'V0', 'VÂRİD-İ HÂTIR', 'varid-i hatır', ' Akla gelen, hatıra gelen.'),
(55390, 'V0', 'VÂRİDÂT', 'varidat', ' (Vâride. C.) Kâr, gelir. * Vârid olan. Bir kimseye veya hazineye ait gelir ve paralar. * Hatıra gelen, içe doğan.'),
(55391, 'V0', 'VÂRİDÎN', 'varidin', ' (Vârid. C.) Gelenler, vâsıl olanlar.'),
(55392, 'V0', 'VARİK', 'varik', ' (C: Vürük) Süs için palanın önüne geçirip astıkları saçaklı kıvrımlı esvap. * Nakışlı kumaştan yapılmış saçaklı palan ve eyer örtüsü.'),
(55393, 'V0', 'VÂRİS', 'varis', ' Cenab-ı Hakk''ın bir ismi. * Mirasçı. Kendisine miras düşen. Mirasa konan. Vefat eden birisinin maddî veya manevî mal ve mülkünde kullanmaya, tasarrufa salâhiyetli olan.'),
(55394, 'V0', 'VÂRİSÎN', 'varisin', ' (Vârisûn) Vâris olanlar. Vârisler.'),
(55395, 'V0', 'VARİŞ', 'variş', ' Bir topluluk yemek yerken davetsiz olarak yemeğe katılan kimse.'),
(55396, 'V0', 'VARTA', 'varta', ' Her çukur yer. Uçurum. * Kurtuluşun zor olduğu yer. Tehlike. Muhatara.'),
(55397, 'V0', 'VARUN', 'varun', ' f. Ters, uğursuz, aksi.'),
(55398, 'V0', 'VA''S (VÜUSE)', 'va''s (vüuse)', ' (C: Vuasâ) şiddet, mihnet.'),
(55399, 'V0', 'VASAA', 'vasaa', ' (C: Vusu) Kız kuşu.'),
(55400, 'V0', 'VASAB', 'vasab', ' (C.: Evsâb) Hastalık. Ağrı.'),
(55401, 'V0', 'VASAFE', 'vasafe', ' Hizmetkârlık.'),
(55402, 'V0', 'VASAİL', 'vasail', ' (Vasâyil) : (Vasile. C.) Yemen''de çıkan çubuklu, alaca kumaşlar.'),
(55403, 'V0', 'VASAT', 'vasat', ' İki şeyin arası. * Orta, merkez, ara. Meydan. Cemiyet muhiti. İç.'),
(55404, 'V0', 'VASAT-ÜL HÂL', 'vasat-ül hal', ' Orta halli, orta halde.'),
(55405, 'V0', 'VASAT-ÜL KAME', 'vasat-ül kame', ' Orta boylu.'),
(55406, 'V0', 'VASATÎ', 'vasati', ' İkisi ortası. Ortalama. Orta halde.'),
(55407, 'V0', 'VASATÎ SAAT', 'vasati saat', ' Hakiki güneşe tâbi olmak üzere, muntazam hareket ettiği tasavvur olunan mevhum bir güneşin, o yerin nısfun nehârından (meridyeninden) arka arkaya iki defa geçişi arasındaki zamanın yirmi dörtte biri.'),
(55408, 'V0', 'VASF', 'vasf', ' Sıfat. Bir kimsenin veya şeyin taşıdığı hâl. Bir kimsenin veya şeyin durumunu anlatarak tarif etmek.'),
(55409, 'V0', 'VASF-I TAHSİNÎ', 'vasf-ı tahsini', ' Bir şeyin mahiyetini beyan etmekten ziyade lâfzını süslemek için kullanılan sıfatlar. Bunlar haşv-i melih kabilindendir.'),
(55410, 'V0', 'VASFETMEK', 'vasfetmek', ' Bir şeyin vasıflarını, hâlini, şeklini veya rengini tarif etmek, anlatmak.'),
(55411, 'V0', 'VASFÎ (VASFİYE)', 'vasfi (vasfiye)', ' Vasıfla, mahiyetiyle alâkalı. Beyan ve tarife dair.'),
(55412, 'V0', 'VASIB', 'vasıb', ' Hasta.'),
(55413, 'V0', 'VASIB', 'vasıb', ' Yerinde duran. Sürekli.'),
(55414, 'V0', 'VASIF', 'vasıf', ' Vasfeden. Bildiren. * Medheden, öven.'),
(55415, 'V0', 'VASIF TERKİBİ', 'vasıf terkibi', ' Gr: Birleşik sıfat. Bir ismin sonuna Farsça bir emir eklenerek yapılan terkib. Meselâ : Zevk-efzâ : Zevk artıran.'),
(55416, 'V0', 'VÂSIK', 'vasık', ' (Vüsuk. dan) Güvenen. İtimad eden.'),
(55417, 'V0', 'VÂSIL', 'vasıl', ' Ulaşan, erişen, kavuşan. Hakka vâsıl olan.'),
(55418, 'V0', 'VÂSILÛN', 'vasılun', ' (Vâsılîn) Hakka, hakikata, marifete ermiş kimseler. Hakka erenler. Yetişenler.'),
(55419, 'V0', 'VÂSIT', 'vasıt', ' Ortada bulunan. * İkisinin ortası.'),
(55420, 'V0', 'VÂSITA', 'vasıta', ' İki şeyi birbirine ulaştıran. * Aracı. Arada bulunan. Vasıtalık eden.'),
(55421, 'V0', 'VÂSITA-İ NECAT', 'vasıta-i necat', ' Necat vasıtası. Kurtuluşa sebep.'),
(55422, 'V0', 'VASİ', 'vasi', ' (Vesâyet. den) Bir ölünün vasiyetini yerine getirmeye me''mur edilen kimse. Bir yetimin veya akılca zayıf, hasta olan bir kimsenin malını idare eden kimse.'),
(55423, 'V0', 'VÂSİ''', 'vasi''', ' (Vasia) Geniş, enli. Bol. Engin. Meydanlı. * Her ihtiyacı olana vergisi kâfi ve bol bol ihsan eden. İlmi cümle eşyayı muhit, rızkı bütün mahlukata şâmil ve rahmeti bütün şeyleri kaplamış olan Allah (C.C.)'),
(55424, 'V0', 'VÂSİ''-İ MUHİTA', 'vasi''-i muhita', ' Muhitin genişliği.'),
(55425, 'V0', 'VASÎD', 'vasid', ' Kapı eşiği.'),
(55426, 'V0', 'VASÎF', 'vasif', ' (C.: Vusafâ - Vesâif) Hizmetçi, uşak.'),
(55427, 'V0', 'VASÎL', 'vasil', ' Birinden aslâ ayrılmaz kimse.'),
(55428, 'V0', 'VASÎLE', 'vasile', ' Geniş yer. * Ucuzluk. * İmaret.'),
(55429, 'V0', 'VASÎT', 'vasit', ' Hakem, aracı. * Orta. '),
(55430, 'V0', 'VASİYET', 'vasiyet', ' Bir işi birisine havale etmek. * Emir. * Fık: Bir malı veya menfaatı, ölümden sonrası için bir şahsa veya bir hayır cihetine teberru yolu ile (yani, meccanen) temlik etmek.'),
