(57327, 'Z0', 'ZİBHA', 'zibha', ' (Zübha) Kuşpalazı, difteri.'),
(57328, 'Z0', 'Zİ''BIK', 'zi''bık', ' Civa.'),
(57329, 'Z0', 'ZİBL', 'zibl', ' Süprüntü. Gübre.'),
(57330, 'Z0', 'ZİBNİYE', 'zibniye', ' Zorla def''edici, zorla kovan.'),
(57331, 'Z0', 'ZİBR', 'zibr', ' Mektup. Kitap.'),
